INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(1, 1, 'ar', 'ريادة في التميز الهندسي', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(2, 2, 'ar', 'جامعة بخارى الحكومية التقنية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(3, 3, 'ar', 'تأسست بموجب المرسوم الرئاسي رقم PP-22، وتمثل القوة الأكاديمية الموحدة للمؤسسات التقنية في بخارى. حائزة على الاستقلالية الأكاديمية والمالية الكاملة منذ عام 2026، لنصنع مستقبلاً رقمياً ومستداماً لأوزبكستان وآسيا الوسطى.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(4, 4, 'ar', 'تواصل', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(5, 5, 'ar', 'استكشف حياة الحرم الجامعي', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(6, 6, 'ar', 'ملف حالة جامعة بخارى', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(7, 7, 'ar', 'حالة الاستقلالية الوطنية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(8, 8, 'ar', 'تعمل كجامعة مستقلة ذاتياً بالكامل منذ 1 يناير 2026.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(9, 9, 'ar', 'مرشح لتصنيف QS العالمي', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(10, 10, 'ar', 'مرشح نشط مدرج في السجل العالمي الرسمي لجامعات QS الأعلى تصنيفاً.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(11, 11, 'ar', 'الإرث التعليمي للجامعة', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(12, 12, 'ar', 'الوريث الشرعي لأول كلية تقنية مسائية تأسست في بخارى عام 1959.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(13, 13, 'ar', 'الاندماج المؤسسي', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(14, 14, 'ar', 'هويتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(15, 15, 'ar', 'تشكلت من خلال دمج معهد بخارى للهندسة والتكنولوجيا ومعهد بخارى لإدارة الموارد الطبيعية (القرار الرئاسي رقم PP-22)، لتجمع الجامعة تحت سقفها نخبة العلماء والباحثين والمرافق التعليمية في المنطقة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(16, 16, 'ar', 'تهدف جامعتنا إلى أن تكون قاعدة تكنولوجية كبرى في أوزبكستان، وتزويد الطلاب بالخبرات الهندسية العميقة، والقدرات البحثية، والاندماج الصناعي بالتعاون المباشر مع شركات كبرى مثل أوزبك نفتغاز.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(17, 17, 'ar', 'الأهداف الاستراتيجية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(18, 18, 'ar', 'الرسالة والرؤية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(19, 19, 'ar', 'رسالتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(20, 20, 'ar', 'تقديم تعليم تقني متميز، وقيادة البحوث العلمية الرائدة، وتخريج نخبة من المهندسين القادرين على إدخال التقنيات الخضراء المتقدمة، وحلول الكيمياء البترولية، والبنية التحتية الرقمية في القطاعات الوطنية.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(21, 21, 'ar', 'رؤيتنا', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(22, 22, 'ar', 'تأمين مكانة بارزة ضمن أفضل 1,000 جامعة عالمية في تصنيف QS بحلول عام 2030، وتأسيس الجامعة كمركز بحثي رئيسي في آسيا الوسطى للرقمنة الصناعية وإدارة الموارد الموفرة للطاقة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(23, 23, 'ar', 'الأخلاقيات التشغيلية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(24, 24, 'ar', 'القيم الأساسية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(25, 25, 'ar', 'النزاهة الأكاديمية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(26, 26, 'ar', 'الالتزام بالأخلاقيات الدولية، والشفافية في نظام درجات ECTS المعتمد، ومكافحة الفساد عبر أنظمة المراقبة والامتثال لدينا.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(27, 27, 'ar', 'الريادة في الابتكار', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(28, 28, 'ar', 'رعاية مواهب ومشاريع الطلاب الناشئة، ودعم التقنيات الوطنية الحائزة على براءات اختراع، وابتكار حلول هندسية رقمية.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(29, 29, 'ar', 'الشمولية العالمية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(30, 30, 'ar', 'دعم الطلاب الدوليين، وتفعيل برامج الشهادات المزدوجة، وتقديم برامج تدريب شاملة للشباب ذوي الاحتياجات الخاصة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(31, 31, 'ar', 'الجامعة في أرقام', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(32, 32, 'ar', 'المؤشرات الأكاديمية والبحثية', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(33, 33, 'ar', 'إحصائيات رئيسية تثبت مكانتنا كمؤسسة هندسية وتكنولوجية رائدة.', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
(34, 34, 'ar', 'الطلاب النشطون', '2026-07-22 11:45:00', '2026-07-22 11:45:00'),
