(209, 25, 'en', 'Academic Integrity', '2026-07-22 11:45:01', '2026-07-22 11:45:01'),
(210, 26, 'en', 'Upholding international ethics, transparency in ECTS grading, and zero tolerance for corruption through our Compliance Control systems.', '2026-07-22 11:45:01', '2026-07-22 11:45:01'),
(211, 27, 'en', 'Innovation Leadership', '2026-07-22 11:45:01', '2026-07-22 11:45:01'),
(212, 28, 'en', 'Fostering student startup talent, supporting national patented technologies, and driving digital engineering solutions.', '2026-07-22 11:45:01', '2026-07-22 11:45:01'),
(213, 29, 'en', 'Global Inclusivity', '2026-07-22 11:45:01', '2026-07-22 11:45:01'),
