INSERT INTO `about_page_content_entry_translations` (`id`, `about_page_content_entry_id`, `locale`, `value`, `created_at`, `updated_at`) VALUES
(501, 134, 'ru', 'Факультет управления природными ресурсами', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(502, 135, 'ru', 'Доц. Барно Бакриддин Кобулова', '2026-07-22 11:45:03', '2026-07-25 04:53:40'),
(503, 136, 'ru', '6 Департаменты', '2026-07-22 11:45:03', '2026-07-24 06:53:42'),
(504, 137, 'ru', 'Водное хозяйство и мелиорация, транспортные системы, промышленная экология и кадастр земли.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(505, 138, 'ru', '/faculty/faculty-of-natural-resources-management', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(506, 139, 'ru', 'border-amber-500/20 hover:border-amber-500', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(507, 140, 'ru', 'Обращение ректора', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(508, 141, 'ru', 'Трансформация технического образования для глобальной эпохи', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(509, 142, 'ru', 'Добро пожаловать в Бухарский государственный технический университет. В 2026 году наш университет перешел на полную академическую и финансовую независимость, внедряя учебные планы ECTS по европейским стандартам. Объединив институты, мы создали научный центр.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(510, 143, 'ru', 'Мы верим, что настоящая инженерия не может преподаваться в отрыве от практики. Именно поэтому наши студенты сотрудничают с заводами и участвуют в программах двойного диплома с Латвией, Беларусью и Турцией. Мы готовим элиту инженерии.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(511, 144, 'ru', 'Биография и достижения ректора', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(512, 145, 'ru', 'Особое внимание', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(513, 146, 'ru', 'Специальное обращение ректора: Защита нашей молодежи', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(514, 147, 'ru', 'Сегодня глобальные процессы привносят вредные привычки в жизнь молодежи без всяких ограничений. Самая опасная из них — наркомания и связанные с ней преступления. Этот порок незаметно крадет здоровье, разум и цели.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(515, 148, 'ru', 'Студентам и молодежи', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(516, 149, 'ru', 'Каждый из вас — сила Будущего нашей страны. От вас требуются дисциплина, бдительность и независимое мышление. Посвятите студенческие годы получению знаний и научных высот. Не поддавайтесь вредному влиянию. Будьте верны профессии.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(517, 150, 'ru', 'Уважаемым родителям', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(518, 151, 'ru', 'Контроль досуга, интересов и душевного состояния наших детей — лучшая мера безопасности. Одна минута доверительной беседы порой предотвращает непоправимые ошибки.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(519, 152, 'ru', 'Уважаемым преподавателям', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(520, 153, 'ru', 'Ваш опыт и авторитет создают основу для мировоззрения молодежи. Профилактика наркомании — это коллективная ответственность. Давайте вместе беречь здоровую духовную атмосферу в нашем университете. Будем внимательны к каждому студенту.', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
(521, 154, 'ru', 'Садокат Гаффоровна Сиддикова', '2026-07-22 11:45:03', '2026-07-22 11:45:03'),
