INSERT INTO `about_page_translations` (`id`, `about_page_id`, `locale`, `content`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', '{"hero":{"badge":"Pioneering Engineering Excellence","title":"Bukhara State Technical University","subtitle":"Established under Presidential Decree PP-22, BSTU represents the unified academic strength of Bukhara\'s technological institutions. Empowered with complete academic and financial autonomy since 2026, we are engineering a sustainable, digital future for Uzbekistan and Central Asia.","admissionsBtn":"Contact","campusBtn":"Explore Campus Life","profileTitle":"BSTU Status Profile","autonomyTitle":"National Autonomy Status","autonomyDesc":"Operating as a fully self-governing university since January 1, 2026.","qsTitle":"QS Ranking Contender","qsDesc":"Active candidate listed in the official QS Top Universities global registry.","legacyTitle":"Educational Legacy","legacyDesc":"Successor of Bukhara\'s earliest engineering faculty founded in 1959."},"identity":{"badge":"Institutional Merge","title":"Our Identity","desc1":"Formed through the integration of the Bukhara Engineering-Technological Institute and the Bukhara Institute of Natural Resources Management (Presidential Resolution No. PP-22), BSTU brings together the region\'s elite scholars, researchers, and campus facilities.","desc2":"Our university aims to become a major technological base in Uzbekistan, equipping students with deep engineering expertise, research capabilities, and global industrial integration, partnering directly with conglomerates like Uzbekneftegaz JSC."},"goals":{"badge":"Strategic Goals","title":"Mission & Vision","missionTitle":"Our Mission","missionDesc":"To deliver premier technical education, drive pioneering scientific research, and produce elite engineering graduates who can introduce advanced green technologies, petrochemical synthesis solutions, and digital infrastructures in national sectors.","visionTitle":"Our Vision","visionDesc":"To secure a prominent position among the top 1,000 global universities in the QS World Rankings by 2030, establishing BSTU as Central Asia\'s primary research hub for industrial digitalization and energy-efficient resource management."},"values":{"badge":"Operational Ethics","title":"Core Values","integrityTitle":"Academic Integrity","integrityDesc":"Upholding international ethics, transparency in ECTS grading, and zero tolerance for corruption through our Compliance Control systems.","innovationTitle":"Innovation Leadership","innovationDesc":"Fostering student startup talent, supporting national patented technologies, and driving digital engineering solutions.","inclusivityTitle":"Global Inclusivity","inclusivityDesc":"Supporting diverse international students, executing dual-degrees, and offering specialized inclusive training for physically challenged youth."},"stats":{"badge":"BSTU in Numbers","title":"Academic & Research Indicators","subtitle":"Key statistics proving our stature as a leading engineering and technological institution.","activeStudents":"Active Students","activeStudentsDesc":"Enrolled in undergraduate and graduate courses","professors":"Professors & Instructors","professorsDesc":"Experienced researchers and academic educators","faculties":"Faculties","facultiesDesc":"Engineering, Technology, Service, and Natural Resources","departments":"Departments","departmentsDesc":"Focusing on modern applied sciences and engineering","research":"Research Centers & Labs","researchDesc":"Developing patented solutions and industrial formulas","techParks":"Technology Parks","techParksDesc":"Supporting student startup ideas and IT solutions","intStudents":"International Students","intStudentsDesc":"Diverse student body from multiple countries","techSchools":"Affiliated Technical Schools","techSchoolsDesc":"Integrated vocational and academic lyceums","items":[{"number":"18,000+","label":"Active Students","desc":"Enrolled in undergraduate and graduate courses","icon":"users","color":"from-blue-500 to-cyan-500"},{"number":"730+","label":"Professors & Instructors","desc":"Experienced researchers and academic educators","icon":"graduation-cap","color":"from-purple-500 to-indigo-500"},{"number":"4","label":"Faculties","desc":"Engineering, Technology, Service, and Natural Resources","icon":"building","color":"from-emerald-500 to-teal-500"},{"number":"24","label":"Departments","desc":"Focusing on modern applied sciences and engineering","icon":"book-open","color":"from-amber-500 to-orange-500"},{"number":"13","label":"Research Centers & Labs","desc":"Developing patented solutions and industrial formulas","icon":"microscope","color":"from-rose-500 to-pink-500"},{"number":"2","label":"Technology Parks","desc":"Supporting student startup ideas and IT solutions","icon":"cpu","color":"from-indigo-500 to-blue-500"},{"number":"250+","label":"International Students","desc":"Diverse student body from multiple countries","icon":"globe","color":"from-cyan-500 to-teal-500"},{"number":"18","label":"Affiliated Technical Schools","desc":"Integrated vocational and academic lyceums","icon":"landmark","color":"from-violet-500 to-purple-500"}]},"facultiesList":{"badge":"Our Structure","title":"Specialized Faculties","subtitle":"Explore the core scientific departments and educational specializations offered at BSTU.","facultyBadge":"BSTU Faculty","deanLabel":"Dean of Faculty:","exploreBtn":"Explore Faculty Departments & Programs","engineering":"Faculty of Engineering","engineeringDean":"Dr. Jasur A. Nematov","engineeringDesc":"Power engineering, architecture, infrastructure design, mechanics, and textile materials science.","technology":"Faculty of Technology","technologyDean":"Dr. Umid S. Mansurov","technologyDesc":"Oil and gas refining, food science, industrial biotechnology, and chemical technologies.","service":"Faculty of Service and Digitalization","serviceDean":"Dr. Sherbek N. Xayitov","serviceDesc":"Artificial intelligence, software engineering, robotics, and applied industrial economics.","natural":"Faculty of Natural Resources Management","naturalDean":"Dr. Alisher M. Kurbanov","naturalDesc":"Irrigation engineering, vehicle manufacturing, industrial ecology, and land management.","engineeringCount":"6 Departments","technologyCount":"6 Departments","serviceCount":"6 Departments","naturalCount":"6 Departments","items":[{"id":"faculty-of-engineering","name":"Faculty of Engineering","dean":"Dr. Khojiyev Aziz Kholmurodovich","count":"6 Departments","desc":"Power engineering, architecture, infrastructure design, mechanics, and textile materials science.","link":"/faculty/faculty-of-engineering","color":"border-blue-500/20 hover:border-blue-500"},{"id":"faculty-of-technology","name":"Faculty of Technology","dean":"Dr. Adizov Rashid Tokhtayevich","count":"6 Departments","desc":"Oil and gas refining, food science, industrial biotechnology, and chemical technologies.","link":"/faculty/faculty-of-technology","color":"border-purple-500/20 hover:border-purple-500"},{"id":"faculty-of-service-and-digitalization","name":"Faculty of Service and Digitalization","dean":"Dr. Khayitov Sherbek Nayimovich","count":"6 Departments","desc":"Artificial intelligence, software engineering, robotics, and applied industrial economics.","link":"/faculty/faculty-of-service-and-digitalization","color":"border-emerald-500/20 hover:border-emerald-500"},{"id":"faculty-of-natural-resources-management","name":"Faculty of Natural Resources Management","dean":"Dr. Barno Bakriddin Kobulova","count":"6 Departments","desc":"Irrigation engineering, vehicle manufacturing, industrial ecology, and land management.","link":"/faculty/faculty-of-natural-resources-management","color":"border-amber-500/20 hover:border-amber-500"}]},"rector":{"badge":"Rector\'s Address","title":"Transforming Technical Education for the Global Era","quote1":"Welcome to Bukhara State Technical University. Our university enters 2026 with complete academic and financial autonomy, allowing us to build modern credit-based ECTS curricula aligned with leading European technical standards. By merging the regional engineering and natural resource institutes, we have built a powerful scientific hub.","quote2":"We believe that true engineering cannot be taught in isolation. That is why our students actively collaborate with national enterprises, conduct scientific research in patented petrochemical formulas, and participate in double-degree programs with Latvia, Belarus, and Turkey. We prepare elite technical specialists ready for global challenges.","profileBtn":"View Rector Profile & Achievements","appealBadge":"Special Awareness","appealTitle":"Rector\'s Special Appeal: Safeguarding Our Youth","appealQuote":"Today, global processes are creating many factors that directly affect the lives of young people. Alongside the endless opportunities of technology, harmful vices also enter without limits. Among these, it is obvious that the most dangerous is drug addiction and related crimes. This vice slowly separates a person from health, consciousness, goals, and dreams.","studentsTitle":"For Student-Youth","studentsDesc":"Each of you is the force prepared for the scientific, technical, and economic development of our country. Discipline, vigilance, independent thinking, and determination are required from you. The student period is the most precious time—fill it with knowledge, research, and high goals. Stay true to your dreams and chosen profession.","parentsTitle":"For Respected Parents","parentsDesc":"Monitoring our children\'s mental state, extracurricular activities, friends, and interests is the most effective measure for their safety. A single word of advice, a minute of conversation sometimes prevents big mistakes. Stay involved in their academic journey and provide constant guidance.","teachersTitle":"For Respected Teachers","teachersDesc":"Your scientific potential, life experience, and educational advice create a solid foundation in the minds of young people. Preventing drug addiction is not just a restriction, but above all, a spiritual strength, collective responsibility, and a conscious way of life. Let us strengthen a healthy environment at our university together.","name":"Sadoqat Gafforovna Siddiqova","degree":"Doctor of Philosophy (PhD) in Pedagogical Sciences"},"timeline":{"badge":"Chronology","title":"Our Historic Journey","subtitle":"From our evening technical roots in 1959 to a fully autonomous, leading state technical university.","year1959Title":"Technical Roots","year1959Desc":"Establishment of the Bukhara Evening General Technical Faculty, laying the foundation for engineering education in the Bukhara oasis to support regional mining and industrial operations.","year1978Title":"Independent Operations","year1978Desc":"Reorganized as the Bukhara Institute of Food and Light Industry Technology, expanding into dedicated chemical technology, textile machinery, and light industry engineering programs.","year2011Title":"Academic Expansion (BETI)","year2011Desc":"Evolved into the Bukhara Engineering-Technological Institute (BETI), establishing major departments in oil & gas refining, automation, and computer science.","year2025Title":"Unified BSTU (Decree PP-22)","year2025Desc":"By Decree of the President of the Republic of Uzbekistan No. PP-22, Bukhara Engineering-Technological Institute and Bukhara Institute of Natural Resources Management merge to form Bukhara State Technical University.","year2026Title":"Complete Autonomy","year2026Desc":"Effective January 1, 2026, BSTU is granted full academic, organizational, and financial independence to implement independent credit systems and accelerate QS rankings.","infographicTitle":"مخطط معلومات تاريخي رسمي","items":[{"year":"1959","title":"Technical Roots","desc":"Establishment of the Bukhara Evening General Technical Faculty, laying the foundation for engineering education in the Bukhara oasis to support regional mining and industrial operations."},{"year":"1978","title":"Independent Operations","desc":"Reorganized as the Bukhara Institute of Food and Light Industry Technology, expanding into dedicated chemical technology, textile machinery, and light industry engineering programs."},{"year":"2011/2013","title":"Academic Expansion (BETI)","desc":"Evolved into the Bukhara Engineering-Technological Institute (BETI), establishing major departments in oil & gas refining, automation, and computer science."},{"year":"2025","title":"Unified BSTU (Decree PP-22)","desc":"By Decree of the President of the Republic of Uzbekistan No. PP-22, Bukhara Engineering-Technological Institute and Bukhara Institute of Natural Resources Management merge to form Bukhara State Technical University."},{"year":"2026","title":"Complete Autonomy","desc":"Effective January 1, 2026, BSTU is granted full academic, organizational, and financial independence to implement independent credit systems and accelerate QS rankings."}]}}', '2026-07-25 23:34:50', '2026-07-30 18:46:56'),
(2, 1, 'uz', '{"hero":{"badge":"Muhandislik salohiyati yetakchisi","title":"Buxoro davlat texnika universiteti","subtitle":"Prezidentning PP-22-sonli qaroriga muvofiq tashkil etilgan BuxDTU Buxoro texnologiya institutlarining birlashgan ilmiy kuchini ifodalaydi. 2026-yildan to\'liq akademik va moliyaviy mustaqillikka ega bo\'lib, biz O\'zbekiston va Markaziy Osiyo uchun raqamli kelajakni muhandislik asosida barpo etmoqdamiz.","admissionsBtn":"Aloqa","campusBtn":"Talabalar hayoti","profileTitle":"BuxDTU maqomi profili","autonomyTitle":"Milliy mustaqillik maqomi","autonomyDesc":"2026-yil 1-yanvardan boshlab to\'liq o\'zini o\'zi boshqaradigan universitet sifatida faoliyat yuritmoqda.","qsTitle":"QS reytingi nomzodi","qsDesc":"Nufuzli QS Top Universities xalqaro reyting ro\'yxatiga kiritilgan faol nomzod.","legacyTitle":"Ta\'limiy meros","legacyDesc":"1959-yilda tashkil etilgan Buxoro birinchi kechki umumtexnika fakulteti vorisi."},"identity":{"badge":"Tarkibiy birlashuv","title":"Bizning shaxsiyatimiz","desc1":"Buxoro muhandislik-texnologiya instituti va Buxoro tabiiy resurslarni boshqarish instituti birlashishi natijasida tashkil etilgan (Prezidentning PP-22-sonli qarori) BuxDTU mintaqaning eng elita olimlari va zamonaviy o\'quv binolarini birlashtiradi.","desc2":"Universitetimiz O\'zbekistonda yirik texnologik baza bo\'lishni, talabalarni chuqur muhandislik bilimlari bilan ta\'minlashni hamda o\'zbekneftegaz AJ kabi sanoat gigantlari bilan hamkorlik qilishni maqsad qilgan."},"goals":{"badge":"Strategik maqsadlar","title":"Missiya va strategiya","missionTitle":"Bizning missiyamiz","missionDesc":"Yuqori sifatli muhandislik ta\'limini taqdim etish, ilg\'or ilmiy tadqiqotlar olib borish va mamlakat sanoat tarmoqlariga ekologik toza va raqamli texnologiyalarni joriy qila oladigan muhandis kadrlarni tayyorlash.","visionTitle":"Bizning qarashlarimiz","visionDesc":"2030-yilga kelib QS xalqaro reytingida dunyoning eng kuchli 1000 ta universiteti qatoridan joy olish, Markaziy Osiyoda sanoat raqamlashtirish bo\'yicha yetakchi tadqiqot markaziga aylanish."},"values":{"badge":"Kanal odobi","title":"Asosiy qadriyatlarimiz","integrityTitle":"Akademik halollik","integrityDesc":"Xalqaro etika me\'yorlariga rioya qilish, baholash tizimida shaffoflik va korrupsiyaga qarshi kurashish tizimi.","innovationTitle":"Innovatsion yetakchilik","innovationDesc":"Talabalarning startap g\'oyalarini qo\'llab-quvvatlash, milliy patentlashtirilgan texnologiyalarni rivojlantirish.","inclusivityTitle":"Global inklyuzivlik","inclusivityDesc":"Xorijiy talabalarni qo\'llab-quvvatlash, qo\'shma ta\'lim dasturlarini amalga oshirish va imkoniyati cheklangan yoshlar uchun sharoitlar yaratish."},"stats":{"badge":"BuxDTU raqamlarda","title":"Akademik va ilmiy ko\'rsatkichlar","subtitle":"Yetakchi muhandislik va texnologiya muassasasi ekanligimizni tasdiqlovchi asosiy ko\'rsatkichlar.","activeStudents":"Faol talabalar","activeStudentsDesc":"Bakalavriat va magistratura yo\'nalishlarida tahsil olayotganlar","professors":"Professor-o\'qituvchilar","professorsDesc":"Tajribali olimlar va ilmiy tadqiqotchilar jamoasi","faculties":"Fakultetlar","facultiesDesc":"Muhandislik, Texnologiya, Xizmat ko\'rsatish va Tabiiy resurslar","departments":"Kafedralar","departmentsDesc":"Zamonaviy amaliy fanlar va muhandislik yo\'nalishlari","research":"Ilmiy markazlar va laboratoriyalar","researchDesc":"Patentlangan sanoat yechimlari va formulalar ustida ishlovchilar","techParks":"Texnoparklar","techParksDesc":"Talabalar startaplari va IT yechimlarni qo\'llab-quvvatlash","intStudents":"Xalqaro talabalar","intStudentsDesc":"Turli mamlakatlardan kelgan xorijiy talabalar","techSchools":"Birlashgan texnikumlar","techSchoolsDesc":"Integratsiyalashgan professional ta\'lim muassasalari","items":[{"number":"18,000+","label":"Faol talabalar","desc":"Bakalavriat va magistratura yo\'nalishlarida tahsil olayotganlar","icon":"users","color":"from-blue-500 to-cyan-500"},{"number":"730+","label":"Professor-o\'qituvchilar","desc":"Tajribali olimlar va ilmiy tadqiqotchilar jamoasi","icon":"graduation-cap","color":"from-purple-500 to-indigo-500"},{"number":"4","label":"Fakultetlar","desc":"Muhandislik, Texnologiya, Xizmat ko\'rsatish va Tabiiy resurslar","icon":"building","color":"from-emerald-500 to-teal-500"},{"number":"24","label":"Kafedralar","desc":"Zamonaviy amaliy fanlar va muhandislik yo\'nalishlari","icon":"book-open","color":"from-amber-500 to-orange-500"},{"number":"13","label":"Ilmiy markazlar va laboratoriyalar","desc":"Patentlangan sanoat yechimlari va formulalar ustida ishlovchilar","icon":"microscope","color":"from-rose-500 to-pink-500"},{"number":"2","label":"Texnoparklar","desc":"Talabalar startaplari va IT yechimlarni qo\'llab-quvvatlash","icon":"cpu","color":"from-indigo-500 to-blue-500"},{"number":"250+","label":"Xalqaro talabalar","desc":"Turli mamlakatlardan kelgan xorijiy talabalar","icon":"globe","color":"from-cyan-500 to-teal-500"},{"number":"18","label":"Birlashgan texnikumlar","desc":"Integratsiyalashgan professional ta\'lim muassasalari","icon":"landmark","color":"from-violet-500 to-purple-500"}]},"facultiesList":{"badge":"Tarkibiy tuzilma","title":"Ixtisoslashgan fakultetlar","subtitle":"BuxDTU tarkibidagi asosiy ilmiy bo\'limlar va ta\'lim yo\'nalishlari bilan tanishing.","facultyBadge":"BuxDTU Fakulteti","deanLabel":"Fakultet dekani:","exploreBtn":"Fakultet kafedralari va dasturlari bilan tanishish","engineering":"Muhandislik fakulteti","engineeringDean":"Dots. Jasur A. Nematov","engineeringDesc":"Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.","technology":"Texnologiya fakulteti","technologyDean":"Prof. Umid S. Mansurov","technologyDesc":"Neft va gazni qayta ishlash, oziq-ovqat texnologiyasi, kimyoviy texnologiyalar va metrologiya.","service":"Xizmat ko\'rsatish va raqamlashtirish fakulteti","serviceDean":"Dr. Sherbek N. Xayitov","serviceDesc":"Sun\'iy intellekt, dasturiy muhandislik, robototexnika va amaliy sanoat iqtisodiyoti.","natural":"Tabiiy resurslarni boshqarish fakulteti","naturalDean":"Dots. Alisher M. Kurbanov","naturalDesc":"Suv xo\'jaligi va melioratsiya, transport tizimlari, sanoat ekologiyasi va yer kadastri.","engineeringCount":"7 ta kafedra","technologyCount":"6 ta kafedra","serviceCount":"7 ta kafedra","naturalCount":"6 ta kafedra","items":[{"id":"faculty-of-engineering","name":"Muhandislik fakulteti","dean":"Dots. Xojiyev Aziz Xolmurodovich","count":"6 Bo\'limlar","desc":"Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.","link":"/faculty/faculty-of-engineering","color":"border-blue-500/20 hover:border-blue-500"},{"id":"faculty-of-technology","name":"Texnologiya fakulteti","dean":"Prof. Adizov Rashid To\'xtayevich","count":"6 Bo\'limlar","desc":"Neft va gazni qayta ishlash, oziq-ovqat texnologiyasi, kimyoviy texnologiyalar va metrologiya.","link":"/faculty/faculty-of-technology","color":"border-purple-500/20 hover:border-purple-500"},{"id":"faculty-of-service-and-digitalization","name":"Xizmat ko\'rsatish va raqamlashtirish fakulteti","dean":"Dr. Xayitov Sherbek Nayimovich","count":"6 Bo\'limlar","desc":"Sun\'iy intellekt, dasturiy muhandislik, robototexnika va amaliy sanoat iqtisodiyoti.","link":"/faculty/faculty-of-service-and-digitalization","color":"border-emerald-500/20 hover:border-emerald-500"},{"id":"faculty-of-natural-resources-management","name":"Tabiiy resurslarni boshqarish fakulteti","dean":"Dots. Qobulova Barno Baxriddin","count":"6 Bo\'limlar","desc":"Suv xo\'jaligi va melioratsiya, transport tizimlari, sanoat ekologiyasi va yer kadastri.","link":"/faculty/faculty-of-natural-resources-management","color":"border-amber-500/20 hover:border-amber-500"}]},"rector":{"badge":"Rector murojaati","title":"Global davr uchun texnik ta\'limni transformatsiya qilish","quote1":"Buxoro davlat texnika universitetiga xush kelibsiz. Universitetimiz 2026-yilga to\'liq akademik va moliyaviy mustaqillik bilan qadam qo\'ydi, bu esa bizga Yevropa ta\'lim standartlariga mos keladigan zamonaviy ECTS kredit tizimini joriy etish imkonini beradi. Birlashgan ilmiy markaz sifatida biz ulkan imkoniyatlar yaratdik.","quote2":"Biz haqiqiy muhandislik amaliyotdan uzilgan holda o\'rganilmasligiga ishonamiz. Shuning uchun talabalarimiz yirik sanoat korxonalari bilan hamkorlik qiladilar va Latviya, Belarus, Turkiya kabi davlatlar bilan qo\'shma dasturlarda ishtirok etadilar. Biz global muammolarga tayyor mutaxassislarni tayyorlaymiz.","profileBtn":"Rektor faoliyati va yutuqlari bilan tanishish","appealBadge":"Maxsus ogohlantirish","appealTitle":"Rektorning yoshlar va jamoatchilikka murojaati","appealQuote":"Bugungi kunda dunyoda yoshlar hayotiga ta\'sir qiluvchi zararli illatlar cheklovsiz kirib kelmoqda. Shular orasida eng xavflisi — giyohvandlik va u bilan bog\'liq jinoyatlardir. Bu illat insonni sog\'liq, ong va maqsadlardan sezdirmasdan uzoqlashtiradi.","studentsTitle":"Talaba-yoshlarga","studentsDesc":"Sizlar mamlakatimiz ilmiy-texnik rivoji uchun tayyorlanayotgan kuchsizlar. Sizdan tartib-intizom, hushyorlik va mustaqil fikrlash talab etiladi. Talabalik davrini bilim va yuksak maqsadlar bilan to\'ldirish sizning qo\'lingizda. Vaqtinchalik qiziqishlarga berilmang. Tanlagan kasbingizga sodiq bo\'ling.","parentsTitle":"Hurmatli ota-onalarga","parentsDesc":"Farzandlarimizning ruhiy holati va darsdan tashqari mashg\'ulotlarini kuzatib borish — xavfsizlik yo\'lidagi eng samarali choradir. Bir daqiqa samimiy suhbat ba\'zan katta xatolarning oldini oladi.","teachersTitle":"Muhtaram ustozlarga","teachersDesc":"Sizning hayotiy tajribangiz yoshlar ongida mustahkam poydevor yaratadi. Giyohvandlikning oldini olish faqat cheklov emas, balki jamoaviy mas\'uliyatdir. Universitetimizda sog\'lom muhitni birgalikda mustahkamlaylik. Har bir talabaga e\'tiborli bo\'laylik.","name":"Sadoqat Gafforovna Siddiqova","degree":"Pedagogika fanlari bo\'yicha falsafa doktori (PhD)"},"timeline":{"badge":"Tarixiy Solnoma","title":"Bizning tarixiy yo\'limiz","subtitle":"1959-yildagi kechki texnika fakultetidan mustaqil yetakchi davlat texnika universitetigacha bo\'lgan yo\'l.","year1959Title":"Kechki ta\'lim asosi","year1959Desc":"Buxoro vohasida muhandislik ta\'limiga poydevor qo\'ygan Buxoro kechki umumtexnika fakultetining tashkil etilishi.","year1978Title":"Mustaqil faoliyat","year1978Desc":"Buxoro oziq-ovqat va yengil sanoat texnologiyasi instituti sifatida qayta tashkil etilishi, kimyo va muhandislik yo\'nalishlarining kengayishi.","year2011Title":"Akademik kengayish","year2011Desc":"Buxoro muhandislik-texnologiya instituti (BMTI) sifatida qayta tashkil etilib, neft-gaz va kompyuter fanlari kafedralari tashkil etilishi.","year2025Title":"Birlashgan BuxDTU (Qaror PP-22)","year2025Desc":"Prezident qarori bilan BMTI va Buxoro tabiiy resurslarni boshqarish institutlari birlashtirilib, yagona BuxDTU tashkil etildi.","year2026Title":"To\'liq mustaqillik","year2026Desc":"2026-yil 1-yanvardan boshlab universitetga mustaqil ta\'lim tizimini joriy etish uchun to\'liq akademik, tashkiliy va moliyaviy mustaqillik berildi.","infographicTitle":"Rasmiy tarixiy infografika","items":[{"year":"1959","title":"Kechki ta\'lim asosi","desc":"Buxoro vohasida muhandislik ta\'limiga poydevor qo\'ygan Buxoro kechki umumtexnika fakultetining tashkil etilishi."},{"year":"1978","title":"Mustaqil faoliyat","desc":"Buxoro oziq-ovqat va yengil sanoat texnologiyasi instituti sifatida qayta tashkil etilishi, kimyo va muhandislik yo\'nalishlarining kengayishi."},{"year":"2011/2013","title":"Akademik kengayish","desc":"Buxoro muhandislik-texnologiya instituti (BMTI) sifatida qayta tashkil etilib, neft-gaz va kompyuter fanlari kafedralari tashkil etilishi."},{"year":"2025","title":"Birlashgan BuxDTU (Qaror PP-22)","desc":"Prezident qarori bilan BMTI va Buxoro tabiiy resurslarni boshqarish institutlari birlashtirilib, yagona BuxDTU tashkil etildi."},{"year":"2026","title":"To\'liq mustaqillik","desc":"2026-yil 1-yanvardan boshlab universitetga mustaqil ta\'lim tizimini joriy etish uchun to\'liq akademik, tashkiliy va moliyaviy mustaqillik berildi."}]}}', '2026-07-25 23:34:50', '2026-07-30 18:46:56'),
(3, 1, 'ru', '{"hero":{"badge":"Лидер инженерного образования","title":"Бухарский государственный технический университет","subtitle":"Основанный указом Президента № ПП-22, БГТУ воплощает единый научно-технический потенциал вузов Бухары. С 2026 года университет обладает полной академической и финансовой независимостью, формируя цифровое будущее для Узбекистана и Центральной Азии.","admissionsBtn":"Контакт","campusBtn":"Студенческая жизнь","profileTitle":"Профиль статуса БГТУ","autonomyTitle":"Национальная автономия","autonomyDesc":"Функционирует как полностью самоуправляемый университет с 1 января 2026 года.","qsTitle":"Кандидат рейтинга QS","qsDesc":"Активный кандидат в официальном глобальном реестре университетов QS Top Universities.","legacyTitle":"Образовательное наследие","legacyDesc":"Преемник первого вечернего общетехнического факультета, созданного в Бухаре в 1959 году."},"identity":{"badge":"Институциональное слияние","title":"Кто мы","desc1":"Созданный путем интеграции Бухарского инженерно-технологического института и Бухарского института управления природными ресурсами, БГТУ объединяет передовых ученых и лучшие учебные комплексы региона.","desc2":"Наш университет стремится стать крупнейшей технологической базой в Узбекистане, предоставляя передовые инженерные знания и сотрудничая с такими гигантами, как АО «Узбекнефтегаз»."},"goals":{"badge":"Стратегические цели","title":"Миссия и Видение","missionTitle":"Наша миссия","missionDesc":"Предоставление высококачественного технического образования, проведение передовых научных исследований и подготовка инженеров нового поколения, способных внедрять экологически чистые и цифровые технологии в промышленности.","visionTitle":"Наше видение","visionDesc":"Войти в топ-1000 лучших университетов мира в международном рейтинге QS к 2030 году и стать главным центром промышленной цифровизации в Центральной Азии."},"values":{"badge":"Профессиональная этика","title":"Ключевые ценности","integrityTitle":"Академическая честность","integrityDesc":"Соблюдение международных этических стандартов, прозрачность оценки кредитов ECTS и эффективное противодействие коррупции.","innovationTitle":"Лидерство в инновациях","innovationDesc":"Поддержка молодежных стартапов, развитие запатентованных технологий и цифровых инженерных решений.","inclusivityTitle":"Глобальная инклюзивность","inclusivityDesc":"Поддержка иностранных студентов, реализация совместных программ и создание инклюзивной среды для молодежи с инвалидностью."},"stats":{"badge":"БГТУ в цифрах","title":"Академические и научные показатели","subtitle":"Ключевые статистические данные, подтверждающие наш статус ведущего технического вуза.","activeStudents":"Активные студенты","activeStudentsDesc":"Обучающиеся на бакалавриате и в магистратуре","professors":"Профессора и преподаватели","professorsDesc":"Опытные исследователи и наставники","faculties":"Факультеты","facultiesDesc":"Инженерия, Технологии, Сервис и Управление ресурсами","departments":"Кафедры","departmentsDesc":"Направленные на современные прикладные науки и инженерию","research":"Научные центры и лаборатории","researchDesc":"Разработка запатентованных промышленных решений и формул","techParks":"Технопарки","techParksDesc":"Поддержка студенческих стартапов и IT-решений","intStudents":"Иностранные студенты","intStudentsDesc":"Студенты, прибывшие на обучение из различных стран","techSchools":"Связанные техникумы","techSchoolsDesc":"Интегрированные учреждения профессионального образования","items":[{"number":"18,000+","label":"Активные студенты","desc":"Обучающиеся на бакалавриате и в магистратуре","icon":"users","color":"from-blue-500 to-cyan-500"},{"number":"730+","label":"Профессора и преподаватели","desc":"Опытные исследователи и наставники","icon":"graduation-cap","color":"from-purple-500 to-indigo-500"},{"number":"4","label":"Факультеты","desc":"Инженерия, Технологии, Сервис и Управление ресурсами","icon":"building","color":"from-emerald-500 to-teal-500"},{"number":"24","label":