0627\\u0644\\u062a\\u0648\\u0633\\u0639 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a (BETI)\",\"year2011Desc\":\"\\u062a\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0645\\u0639\\u0647\\u062f \\u0644\\u064a\\u0635\\u0628\\u062d \\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 (BETI)\\u060c \\u0648\\u062a\\u0623\\u0633\\u064a\\u0633 \\u0623\\u0642\\u0633\\u0627\\u0645 \\u0643\\u0628\\u0631\\u0649 \\u0641\\u064a \\u062a\\u0643\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0641\\u0637\\u060c \\u0648\\u0627\\u0644\\u0623\\u062a\\u0645\\u062a\\u0629\\u060c \\u0648\\u0639\\u0644\\u0648\\u0645 \\u0627\\u0644\\u0643\\u0645\\u0628\\u064a\\u0648\\u062a\\u0631.\",\"year2025Title\":\"\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062d\\u062f\\u0629\",\"year2025Desc\":\"\\u0628\\u0645\\u0648\\u062c\\u0628 \\u0627\\u0644\\u0645\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0631\\u0626\\u0627\\u0633\\u064a \\u0631\\u0642\\u0645 PP-22\\u060c \\u062a\\u0645 \\u062f\\u0645\\u062c \\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0648\\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0644\\u062a\\u0634\\u0643\\u064a\\u0644 \\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629.\",\"year2026Title\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629\",\"year2026Desc\":\"\\u0627\\u0639\\u062a\\u0628\\u0627\\u0631\\u0627\\u064b \\u0645\\u0646 1 \\u064a\\u0646\\u0627\\u064a\\u0631 2026\\u060c \\u0645\\u0646\\u062d\\u062a \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0648\\u062a\\u0646\\u0638\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u0644\\u0629 \\u0648\\u062a\\u0633\\u0631\\u064a\\u0639 \\u062a\\u0635\\u0646\\u064a\\u0641\\u0647\\u0627 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a.\",\"infographicTitle\":\"\\u0645\\u062e\\u0637\\u0637 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u062a\\u0627\\u0631\\u064a\\u062e\\u064a \\u0631\\u0633\\u0645\\u064a\",\"items\":[{\"year\":\"1959\",\"title\":\"\\u0627\\u0644\\u062c\\u0630\\u0648\\u0631 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649\",\"desc\":\"\\u062a\\u0623\\u0633\\u064a\\u0633 \\u0643\\u0644\\u064a\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0626\\u064a\\u0629\\u060c \\u0648\\u0648\\u0636\\u0639 \\u062d\\u062c\\u0631 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633 \\u0644\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u064a \\u0641\\u064a \\u0648\\u0627\\u062d\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u062d\\u0644\\u064a\\u0629.\"},{\"year\":\"1978\",\"title\":\"\\u0627\\u0644\\u062a\\u0634\\u063a\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u0644\",\"desc\":\"\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0643\\u0644\\u064a\\u0629 \\u0644\\u062a\\u0635\\u0628\\u062d \\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0627\\u0644\\u0623\\u063a\\u0630\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u062e\\u0641\\u064a\\u0641\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0633\\u0639 \\u0641\\u064a \\u0623\\u0642\\u0633\\u0627\\u0645 \\u0627\\u0644\\u0643\\u064a\\u0645\\u064a\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0622\\u0644\\u0627\\u062a \\u0627\\u0644\\u0646\\u0633\\u064a\\u062c\\u064a\\u0629.\"},{\"year\":\"2011\\/2013\",\"title\":\"\\u0627\\u0644\\u062a\\u0648\\u0633\\u0639 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a (BETI)\",\"desc\":\"\\u062a\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0645\\u0639\\u0647\\u062f \\u0644\\u064a\\u0635\\u0628\\u062d \\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 (BETI)\\u060c \\u0648\\u062a\\u0623\\u0633\\u064a\\u0633 \\u0623\\u0642\\u0633\\u0627\\u0645 \\u0643\\u0628\\u0631\\u0649 \\u0641\\u064a \\u062a\\u0643\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0641\\u0637\\u060c \\u0648\\u0627\\u0644\\u0623\\u062a\\u0645\\u062a\\u0629\\u060c \\u0648\\u0639\\u0644\\u0648\\u0645 \\u0627\\u0644\\u0643\\u0645\\u0628\\u064a\\u0648\\u062a\\u0631.\"},{\"year\":\"2025\",\"title\":\"\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062d\\u062f\\u0629\",\"desc\":\"\\u0628\\u0645\\u0648\\u062c\\u0628 \\u0627\\u0644\\u0645\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0631\\u0626\\u0627\\u0633\\u064a \\u0631\\u0642\\u0645 PP-22\\u060c \\u062a\\u0645 \\u062f\\u0645\\u062c \\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0648\\u0645\\u0639\\u0647\\u062f \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0644\\u062a\\u0634\\u0643\\u064a\\u0644 \\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629.\"},{\"year\":\"2026\",\"title\":\"\\u0627\\u0644\\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629\",\"desc\":\"\\u0627\\u0639\\u062a\\u0628\\u0627\\u0631\\u0627\\u064b \\u0645\\u0646 1 \\u064a\\u0646\\u0627\\u064a\\u0631 2026\\u060c \\u0645\\u0646\\u062d\\u062a \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0648\\u062a\\u0646\\u0638\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u0644\\u0629 \\u0648\\u062a\\u0633\\u0631\\u064a\\u0639 \\u062a\\u0635\\u0646\\u064a\\u0641\\u0647\\u0627 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a.\"}]}},\"created_at\":\"2026-07-22T13:24:57.000000Z\",\"updated_at\":\"2026-07-22T13:57:44.000000Z\"},{\"id\":1,\"about_page_id\":1,\"locale\":\"en\",\"content\":{\"hero\":{\"badge\":\"Pioneering Engineering Excellence\",\"title\":\"Bukhara State Technical University\",\"subtitle\":\"Established under Presidential Decree PP-22, BSTU represents the unified academic strength of Bukhara\'s technological institutions. Empowered with complete academic and financial autonomy since 2026, we are engineering a sustainable, digital future for Uzbekistan and Central Asia.\",\"admissionsBtn\":\"Contact\",\"campusBtn\":\"Explore Campus Life\",\"profileTitle\":\"BSTU Status Profile\",\"autonomyTitle\":\"National Autonomy Status\",\"autonomyDesc\":\"Operating as a fully self-governing university since January 1, 2026.\",\"qsTitle\":\"QS Ranking Contender\",\"qsDesc\":\"Active candidate listed in the official QS Top Universities global registry.\",\"legacyTitle\":\"Educational Legacy\",\"legacyDesc\":\"Successor of Bukhara\'s earliest engineering faculty founded in 1959.\"},\"identity\":{\"badge\":\"Institutional Merge\",\"title\":\"Our Identity\",\"desc1\":\"Formed through the integration of the Bukhara Engineering-Technological Institute and the Bukhara Institute of Natural Resources Management (Presidential Resolution No. PP-22), BSTU brings together the region\'s elite scholars, researchers, and campus facilities.\",\"desc2\":\"Our university aims to become a major technological base in Uzbekistan, equipping students with deep engineering expertise, research capabilities, and global industrial integration, partnering directly with conglomerates like Uzbekneftegaz JSC.\"},\"goals\":{\"badge\":\"Strategic Goals\",\"title\":\"Mission & Vision\",\"missionTitle\":\"Our Mission\",\"missionDesc\":\"To deliver premier technical education, drive pioneering scientific research, and produce elite engineering graduates who can introduce advanced green technologies, petrochemical synthesis solutions, and digital infrastructures in national sectors.\",\"visionTitle\":\"Our Vision\",\"visionDesc\":\"To secure a prominent position among the top 1,000 global universities in the QS World Rankings by 2030, establishing BSTU as Central Asia\'s primary research hub for industrial digitalization and energy-efficient resource management.\"},\"values\":{\"badge\":\"Operational Ethics\",\"title\":\"Core Values\",\"integrityTitle\":\"Academic Integrity\",\"integrityDesc\":\"Upholding international ethics, transparency in ECTS grading, and zero tolerance for corruption through our Compliance Control systems.\",\"innovationTitle\":\"Innovation Leadership\",\"innovationDesc\":\"Fostering student startup talent, supporting national patented technologies, and driving digital engineering solutions.\",\"inclusivityTitle\":\"Global Inclusivity\",\"inclusivityDesc\":\"Supporting diverse international students, executing dual-degrees, and offering specialized inclusive training for physically challenged youth.\"},\"stats\":{\"badge\":\"BSTU in Numbers\",\"title\":\"Academic & Research Indicators\",\"subtitle\":\"Key statistics proving our stature as a leading engineering and technological institution.\",\"activeStudents\":\"Active Students\",\"activeStudentsDesc\":\"Enrolled in undergraduate and graduate courses\",\"professors\":\"Professors & Instructors\",\"professorsDesc\":\"Experienced researchers and academic educators\",\"faculties\":\"Faculties\",\"facultiesDesc\":\"Engineering, Technology, Service, and Natural Resources\",\"departments\":\"Departments\",\"departmentsDesc\":\"Focusing on modern applied sciences and engineering\",\"research\":\"Research Centers & Labs\",\"researchDesc\":\"Developing patented solutions and industrial formulas\",\"techParks\":\"Technology Parks\",\"techParksDesc\":\"Supporting student startup ideas and IT solutions\",\"intStudents\":\"International Students\",\"intStudentsDesc\":\"Diverse student body from multiple countries\",\"techSchools\":\"Affiliated Technical Schools\",\"techSchoolsDesc\":\"Integrated vocational and academic lyceums\",\"items\":[{\"number\":\"18,000+\",\"label\":\"Active Students\",\"desc\":\"Enrolled in undergraduate and graduate courses\",\"icon\":\"users\",\"color\":\"from-blue-500 to-cyan-500\"},{\"number\":\"730+\",\"label\":\"Professors & Instructors\",\"desc\":\"Experienced researchers and academic educators\",\"icon\":\"graduation-cap\",\"color\":\"from-purple-500 to-indigo-500\"},{\"number\":\"4\",\"label\":\"Faculties\",\"desc\":\"Engineering, Technology, Service, and Natural Resources\",\"icon\":\"building\",\"color\":\"from-emerald-500 to-teal-500\"},{\"number\":\"24\",\"label\":\"Departments\",\"desc\":\"Focusing on modern applied sciences and engineering\",\"icon\":\"book-open\",\"color\":\"from-amber-500 to-orange-500\"},{\"number\":\"13\",\"label\":\"Research Centers & Labs\",\"desc\":\"Developing patented solutions and industrial formulas\",\"icon\":\"microscope\",\"color\":\"from-rose-500 to-pink-500\"},{\"number\":\"2\",\"label\":\"Technology Parks\",\"desc\":\"Supporting student startup ideas and IT solutions\",\"icon\":\"cpu\",\"color\":\"from-indigo-500 to-blue-500\"},{\"number\":\"250+\",\"label\":\"International Students\",\"desc\":\"Diverse student body from multiple countries\",\"icon\":\"globe\",\"color\":\"from-cyan-500 to-teal-500\"},{\"number\":\"18\",\"label\":\"Affiliated Technical Schools\",\"desc\":\"Integrated vocational and academic lyceums\",\"icon\":\"landmark\",\"color\":\"from-violet-500 to-purple-500\"}]},\"facultiesList\":{\"badge\":\"Our Structure\",\"title\":\"Specialized Faculties\",\"subtitle\":\"Explore the core scientific departments and educational specializations offered at BSTU.\",\"facultyBadge\":\"BSTU Faculty\",\"deanLabel\":\"Dean of Faculty:\",\"exploreBtn\":\"Explore Faculty Departments & Programs\",\"engineering\":\"Faculty of Engineering\",\"engineeringDean\":\"Dr. Jasur A. Nematov\",\"engineeringDesc\":\"Power engineering, architecture, infrastructure design, mechanics, and textile materials science.\",\"technology\":\"Faculty of Technology\",\"technologyDean\":\"Dr. Umid S. Mansurov\",\"technologyDesc\":\"Oil and gas refining, food science, industrial biotechnology, and chemical technologies.\",\"service\":\"Faculty of Service and Digitalization\",\"serviceDean\":\"Dr. Sherbek N. Xayitov\",\"serviceDesc\":\"Artificial intelligence, software engineering, robotics, and applied industrial economics.\",\"natural\":\"Faculty of Natural Resources Management\",\"naturalDean\":\"Dr. Alisher M. Kurbanov\",\"naturalDesc\":\"Irrigation engineering, vehicle manufacturing, industrial ecology, and land management.\",\"engineeringCount\":\"6 Departments\",\"technologyCount\":\"6 Departments\",\"serviceCount\":\"6 Departments\",\"naturalCount\":\"6 Departments\",\"items\":[{\"id\":\"faculty-of-engineering\",\"name\":\"Faculty of Engineering\",\"dean\":\"Dr. Jasur A. Nematov\",\"count\":\"6 Departments\",\"desc\":\"Power engineering, architecture, infrastructure design, mechanics, and textile materials science.\",\"link\":\"\\/faculty\\/faculty-of-engineering\",\"color\":\"border-blue-500\\/20 hover:border-blue-500\"},{\"id\":\"faculty-of-technology\",\"name\":\"Faculty of Technology\",\"dean\":\"Dr. Umid S. Mansurov\",\"count\":\"6 Departments\",\"desc\":\"Oil and gas refining, food science, industrial biotechnology, and chemical technologies.\",\"link\":\"\\/faculty\\/faculty-of-technology\",\"color\":\"border-purple-500\\/20 hover:border-purple-500\"},{\"id\":\"faculty-of-service-and-digitalization\",\"name\":\"Faculty of Service and Digitalization\",\"dean\":\"Dr. Sherbek N. Xayitov\",\"count\":\"6 Departments\",\"desc\":\"Artificial intelligence, software engineering, robotics, and applied industrial economics.\",\"link\":\"\\/faculty\\/faculty-of-service-and-digitalization\",\"color\":\"border-emerald-500\\/20 hover:border-emerald-500\"},{\"id\":\"faculty-of-natural-resources-management\",\"name\":\"Faculty of Natural Resources Management\",\"dean\":\"Dr. Alisher M. Kurbanov\",\"count\":\"6 Departments\",\"desc\":\"Irrigation engineering, vehicle manufacturing, industrial ecology, and land management.\",\"link\":\"\\/faculty\\/faculty-of-natural-resources-management\",\"color\":\"border-amber-500\\/20 hover:border-amber-500\"}]},\"rector\":{\"badge\":\"Rector\'s Address\",\"title\":\"Transforming Technical Education for the Global Era\",\"quote1\":\"Welcome to Bukhara State Technical University. Our university enters 2026 with complete academic and financial autonomy, allowing us to build modern credit-based ECTS curricula aligned with leading European technical standards. By merging the regional engineering and natural resource institutes, we have built a powerful scientific hub.\",\"quote2\":\"We believe that true engineering cannot be taught in isolation. That is why our students actively collaborate with national enterprises, conduct scientific research in patented petrochemical formulas, and participate in double-degree programs with Latvia, Belarus, and Turkey. We prepare elite technical specialists ready for global challenges.\",\"profileBtn\":\"View Rector Profile & Achievements\",\"appealBadge\":\"Special Awareness\",\"appealTitle\":\"Rector\'s Special Appeal: Safeguarding Our Youth\",\"appealQuote\":\"Today, global processes are creating many factors that directly affect the lives of young people. Alongside the endless opportunities of technology, harmful vices also enter without limits. Among these, it is obvious that the most dangerous is drug addiction and related crimes. This vice slowly separates a person from health, consciousness, goals, and dreams.\",\"studentsTitle\":\"For Student-Youth\",\"studentsDesc\":\"Each of you is the force prepared for the scientific, technical, and economic development of our country. Discipline, vigilance, independent thinking, and determination are required from you. The student period is the most precious time\\u2014fill it with knowledge, research, and high goals. Stay true to your dreams and chosen profession.\",\"parentsTitle\":\"For Respected Parents\",\"parentsDesc\":\"Monitoring our children\'s mental state, extracurricular activities, friends, and interests is the most effective measure for their safety. A single word of advice, a minute of conversation sometimes prevents big mistakes. Stay involved in their academic journey and provide constant guidance.\",\"teachersTitle\":\"For Respected Teachers\",\"teachersDesc\":\"Your scientific potential, life experience, and educational advice create a solid foundation in the minds of young people. Preventing drug addiction is not just a restriction, but above all, a spiritual strength, collective responsibility, and a conscious way of life. Let us strengthen a healthy environment at our university together.\",\"name\":\"Sadoqat Gafforovna Siddiqova\",\"degree\":\"Doctor of Philosophy (PhD) in Pedagogical Sciences\"},\"timeline\":{\"badge\":\"Chronology\",\"title\":\"Our Historic Journey\",\"subtitle\":\"From our evening technical roots in 1959 to a fully autonomous, leading state technical university.\",\"year1959Title\":\"Technical Roots\",\"year1959Desc\":\"Establishment of the Bukhara Evening General Technical Faculty, laying the foundation for engineering education in the Bukhara oasis to support regional mining and industrial operations.\",\"year1978Title\":\"Independent Operations\",\"year1978Desc\":\"Reorganized as the Bukhara Institute of Food and Light Industry Technology, expanding into dedicated chemical technology, textile machinery, and light industry engineering programs.\",\"year2011Title\":\"Academic Expansion (BETI)\",\"year2011Desc\":\"Evolved into the Bukhara Engineering-Technological Institute (BETI), establishing major departments in oil & gas refining, automation, and computer science.\",\"year2025Title\":\"Unified BSTU (Decree PP-22)\",\"year2025Desc\":\"By Decree of the President of the Republic of Uzbekistan No. PP-22, Bukhara Engineering-Technological Institute and Bukhara Institute of Natural Resources Management merge to form Bukhara State Technical University.\",\"year2026Title\":\"Complete Autonomy\",\"year2026Desc\":\"Effective January 1, 2026, BSTU is granted full academic, organizational, and financial independence to implement independent credit systems and accelerate QS rankings.\",\"items\":[{\"year\":\"1959\",\"title\":\"Technical Roots\",\"desc\":\"Establishment of the Bukhara Evening General Technical Faculty, laying the foundation for engineering education in the Bukhara oasis to support regional mining and industrial operations.\"},{\"year\":\"1978\",\"title\":\"Independent Operations\",\"desc\":\"Reorganized as the Bukhara Institute of Food and Light Industry Technology, expanding into dedicated chemical technology, textile machinery, and light industry engineering programs.\"},{\"year\":\"2011\\/2013\",\"title\":\"Academic Expansion (BETI)\",\"desc\":\"Evolved into the Bukhara Engineering-Technological Institute (BETI), establishing major departments in oil & gas refining, automation, and computer science.\"},{\"year\":\"2025\",\"title\":\"Unified BSTU (Decree PP-22)\",\"desc\":\"By Decree of the President of the Republic of Uzbekistan No. PP-22, Bukhara Engineering-Technological Institute and Bukhara Institute of Natural Resources Management merge to form Bukhara State Technical University.\"},{\"year\":\"2026\",\"title\":\"Complete Autonomy\",\"desc\":\"Effective January 1, 2026, BSTU is granted full academic, organizational, and financial independence to implement independent credit systems and accelerate QS rankings.\"}]}},\"created_at\":\"2026-07-22T13:24:57.000000Z\",\"updated_at\":\"2026-07-22T13:57:44.000000Z\"},{\"id\":3,\"about_page_id\":1,\"locale\":\"ru\",\"content\":{\"hero\":{\"badge\":\"\\u041b\\u0438\\u0434\\u0435\\u0440 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u043e\\u0433\\u043e \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f\",\"title\":\"\\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0433\\u043e\\u0441\\u0443\\u0434\\u0430\\u0440\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\",\"subtitle\":\"\\u041e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0443\\u043a\\u0430\\u0437\\u043e\\u043c \\u041f\\u0440\\u0435\\u0437\\u0438\\u0434\\u0435\\u043d\\u0442\\u0430 \\u2116 \\u041f\\u041f-22, \\u0411\\u0413\\u0422\\u0423 \\u0432\\u043e\\u043f\\u043b\\u043e\\u0449\\u0430\\u0435\\u0442 \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u043d\\u0430\\u0443\\u0447\\u043d\\u043e-\\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043e\\u0442\\u0435\\u043d\\u0446\\u0438\\u0430\\u043b \\u0432\\u0443\\u0437\\u043e\\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u044b. \\u0421 2026 \\u0433\\u043e\\u0434\\u0430 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442 \\u043e\\u0431\\u043b\\u0430\\u0434\\u0430\\u0435\\u0442 \\u043f\\u043e\\u043b\\u043d\\u043e\\u0439 \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0438 \\u0444\\u0438\\u043d\\u0430\\u043d\\u0441\\u043e\\u0432\\u043e\\u0439 \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c\\u044e, \\u0444\\u043e\\u0440\\u043c\\u0438\\u0440\\u0443\\u044f \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u043e\\u0435 \\u0431\\u0443\\u0434\\u0443\\u0449\\u0435\\u0435 \\u0434\\u043b\\u044f \\u0423\\u0437\\u0431\\u0435\\u043a\\u0438\\u0441\\u0442\\u0430\\u043d\\u0430 \\u0438 \\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0410\\u0437\\u0438\\u0438.\",\"admissionsBtn\":\"\\u041a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\",\"campusBtn\":\"\\u0421\\u0442\\u0443\\u0434\\u0435\\u043d\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0436\\u0438\\u0437\\u043d\\u044c\",\"profileTitle\":\"\\u041f\\u0440\\u043e\\u0444\\u0438\\u043b\\u044c \\u0441\\u0442\\u0430\\u0442\\u0443\\u0441\\u0430 \\u0411\\u0413\\u0422\\u0423\",\"autonomyTitle\":\"\\u041d\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0430\\u0432\\u0442\\u043e\\u043d\\u043e\\u043c\\u0438\\u044f\",\"autonomyDesc\":\"\\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u043e\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442 \\u043a\\u0430\\u043a \\u043f\\u043e\\u043b\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u0441\\u0430\\u043c\\u043e\\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c\\u044b\\u0439 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442 \\u0441 1 \\u044f\\u043d\\u0432\\u0430\\u0440\\u044f 2026 \\u0433\\u043e\\u0434\\u0430.\",\"qsTitle\":\"\\u041a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442 \\u0440\\u0435\\u0439\\u0442\\u0438\\u043d\\u0433\\u0430 QS\",\"qsDesc\":\"\\u0410\\u043a\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 \\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442 \\u0432 \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c \\u0433\\u043b\\u043e\\u0431\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c \\u0440\\u0435\\u0435\\u0441\\u0442\\u0440\\u0435 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u043e\\u0432 QS Top Universities.\",\"legacyTitle\":\"\\u041e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0435 \\u043d\\u0430\\u0441\\u043b\\u0435\\u0434\\u0438\\u0435\",\"legacyDesc\":\"\\u041f\\u0440\\u0435\\u0435\\u043c\\u043d\\u0438\\u043a \\u043f\\u0435\\u0440\\u0432\\u043e\\u0433\\u043e \\u0432\\u0435\\u0447\\u0435\\u0440\\u043d\\u0435\\u0433\\u043e \\u043e\\u0431\\u0449\\u0435\\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\\u0430, \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u0432 \\u0411\\u0443\\u04