\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629\",\"year2026Desc\":\"\\u0627\\u0639\\u062a\\u0628\\u0627\\u0631\\u0627\\u064b \\u0645\\u0646 1 \\u064a\\u0646\\u0627\\u064a\\u0631 2026\\u060c \\u0645\\u0646\\u062d\\u062a \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0648\\u062a\\u0646\\u0638\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0623\\u0646\\u0638\\u0645\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u0644\\u0629 \\u0648\\u062a\\u0633\\u0631\\u064a\\u0639 \\u062a\\u0635\\u0646\\u064a\\u0641\\u0647\\u0627 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a.\",\"infographicTitle\":\"\\u0645\\u062e\\u0637\\u0637 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u062a\\u0627\\u0631\\u064a\\u062e\\u064a \\u0631\\u0633\\u0645\\u064a\",\"items\":[{\"year\":\"1959\",\"title\":\"\\u0627\\u0644\\u062c\\u0630\\u0648\\u0631 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649\",\"desc\":\"\\u062a\\u0623\\u0633\\u064a\\u0633 \\u0643\\u0644\\u064a\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0626\\u064a\\u0629\\u060c \\u0648\\u0648\\u0636\\u0639 \\u062d\\u062c\\u0631 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633 \\u0644\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u064a \\u0641\\u064a \\u0648\\u0627\\u062d\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u06