(200, 1, 'update', 'App\\Models\\AboutPageContentEntry', 1, NULL, '{\"entry\":\"faculties:1\",\"payload\":{\"section\":\"facultiesList\",\"type\":\"faculty_item\",\"key\":\"faculties_1\",\"metadata\":{\"id\":\"faculty-of-technology\",\"link\":\"\\/faculty\\/faculty-of-technology\",\"color\":\"border-purple-500\\/20 hover:border-purple-500\"},\"translations\":{\"ar\":{\"name\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627\",\"dean\":\"\\u0623.\\u062f. \\u0623\\u0648\\u0645\\u064a\\u062f \\u0645\\u0646\\u0635\\u0648\\u0631\\u0648\\u0641\",\"count\":\"6 \\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645\",\"description\":\"\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u062a\\u0643\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0641\\u0637 \\u0648\\u0627\\u0644\\u063a\\u0627\\u0632\\u060c \\u0639\\u0644\\u0648\\u0645 \\u0627\\u0644\\u0623\\u063a\\u0630\\u064a\\u0629\\u060c \\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0627\\u0644\\u062d\\u064a\\u0648\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0645\\u0642\\u0627\\u064a\\u064a\\u0633 \\u0648\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629.\"},\"en\":{\"name\":\"Faculty of Technology\",\"dean\":\"Dr. Umid S. Mansurov\",\"count\":\"6 Departments\",\"description\":\"Oil and gas refining, food science, industrial biotechnology, and chemical technologies.\"},\"ru\":{\"name\":\"\\u0422\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\",\"dean\":\"\\u041f\\u0440\\u043e\\u0444. \\u0423\\u043c\\u0438\\u0434 \\u0421. \\u041c\\u0430\\u043d\\u0441\\u0443\\u0440\\u043e\\u0432\",\"count\":\"6 \\u0414\\u0435\\u043f\\u0430\\u0440\\u0442\\u0430\\u043c\\u0435\\u043d\\u0442\\u044b\",\"description\":\"\\u0422\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f \\u043f\