(201, 1, 'update', 'App\\Models\\AboutPageContentEntry', 1, NULL, '{\"entry\":\"faculties:2\",\"payload\":{\"section\":\"facultiesList\",\"type\":\"faculty_item\",\"key\":\"faculties_2\",\"metadata\":{\"id\":\"faculty-of-service-and-digitalization\",\"link\":\"\\/faculty\\/faculty-of-service-and-digitalization\",\"color\":\"border-emerald-500\\/20 hover:border-emerald-500\"},\"translations\":{\"ar\":{\"name\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a \\u0648\\u0627\\u0644\\u0631\\u0642\\u0645\\u0646\\u0629\",\"dean\":\"\\u062f. \\u0634\\u064a\\u0631\\u0628\\u064a\\u0643 \\u062e\\u0627\\u064a\\u064a\\u062a\\u0648\\u0641\",\"count\":\"6 \\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645\",\"description\":\"\\u0627\\u0644\\u0630\\u0643\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a\\u060c \\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0628\\u0631\\u0645\\u062c\\u064a\\u0627\\u062a\\u060c \\u0627\\u0644\\u0631\\u0648\\u0628\\u0648\\u062a\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0627\\u0644\\u0622\\u0644\\u064a \\u0648\\u0627\\u0644\\u0627\\u0642\\u062a\\u0635\\u0627\\u062f \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642\\u064a.\"},\"en\":{\"name\":\"Faculty of Service and Digitalization\",\"dean\":\"Dr. Sherbek N. Xayitov\",\"count\":\"6 Departments\",\"description\":\"Artificial intelligence, software engineering, robotics, and applied industrial economics.\"},\"ru\":{\"name\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0441\\u0435\\u0440\\u0432\\u0438\\u0441\\u0430 \\u0438 \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438\",\"dean\":\"\\u0414-\\u0440 \\u0428\\u0435\\u0440\\u0431\\u0435\\u043a \\u041d. \\u0425\\u0430\\u0439\\u0438\\u0442\\u043e\\u0432\",\"count\":\"6 \\u0414\\u0435\\u043f\\u0430\\u0440\\u0442\\u0430\\u043c\\u0435\\u043d\\u0442\\u044b\",\"description\":\"\\u0418\\u0441\\u043a\\u0443\\u0441\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0442\\u0435\\u043b\\u043b\\u0435\\u043a\\u0442, \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c\\u043d\\u0430\\u044f \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u0438\\u044f, \\u0440\\u043e\\u0431\\u043e\\u0442\\u043e\\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0430 \\u0438 \\u043f\\u0440\\u0438\\u043a\\u043b\\u0430\\u0434\\u043d\\u0430\\u044f \\u044d\\u043a\\u043e\\u043d\\u043e\\u043c\\u0438\\u043a\\u0430.\"},\"uz\":{\"name\":\"Xizmat ko\'rsatish va raqamlashtirish fakulteti\",\"dean\":\"Dr. Sherbek N. Xayitov\",\"count\":\"6 Bo\'limlar\",\"description\":\"Sun\'iy intellekt, dasturiy muhandislik, robototexnika va amaliy sanoat iqtisodiyoti.\"}}}}', '127.0.0.1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-07-24 11:53:41');
