INSERT INTO `faculty_translations` (`id`, `faculty_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'Faculty of Technology', 'Technology', 'The Faculty of Technology trains specialists for chemical technology, food production, oil and gas processing, metrology and agricultural product processing.', '[]', ' - BSTU', 'The Faculty of Technology trains specialists for chemical technology, food production, oil and gas processing, metrology and agricultural product processing.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(2, 1, 'uz', 'Texnologiya fakulteti', 'Texnologiya', 'Texnologiya fakulteti kimyoviy texnologiya, oziq-ovqat ishlab chiqarish, neft va gazni qayta ishlash, metrologiya hamda qishloq xo‘jaligi mahsulotlarini qayta ishlash bo‘yicha mutaxassislar tayyorlaydi.', '[]', ' - BSTU', 'Texnologiya fakulteti kimyoviy texnologiya, oziq-ovqat ishlab chiqarish, neft va gazni qayta ishlash, metrologiya hamda qishloq xo‘jaligi mahsulotlarini qayta ishlash bo‘yicha mutaxassislar tayyorlaydi.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(3, 1, 'ru', 'Технологический факультет', 'Технология', 'Технологический факультет готовит специалистов по химической технологии, пищевому производству, переработке нефти и газа, метрологии и переработке сельхозпродукции.', '[]', ' - BSTU', 'Технологический факультет готовит специалистов по химической технологии, пищевому производству, переработке нефти и газа, метрологии и переработке сельхозпродукции.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(4, 1, 'ar', 'كلية التكنولوجيا', 'التكنولوجيا', 'تعد كلية التكنولوجيا متخصصين في التكنولوجيا الكيميائية وإنتاج الأغذية ومعالجة النفط والغاز والمترولوجيا ومعالجة المنتجات الزراعية.', '[]', ' - BSTU', 'تعد كلية التكنولوجيا متخصصين في التكنولوجيا الكيميائية وإنتاج الأغذية ومعالجة النفط والغاز والمترولوجيا ومعالجة المنتجات الزراعية.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(5, 2, 'en', 'Faculty of Service and Digitalization', 'Service & Digitalization', 'The faculty brings together economics, management, tourism, ICT, automation, exact sciences, social sciences and language education for a digital university environment.', '[]', ' - BSTU', 'The faculty brings together economics, management, tourism, ICT, automation, exact sciences, social sciences and language education for a digital university environment.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(6, 2, 'uz', 'Servis va raqamlashtirish fakulteti', 'Servis va raqamlashtirish', 'Fakultet raqamli universitet muhitida iqtisodiyot, menejment, turizm, AKT, avtomatlashtirish, aniq fanlar, ijtimoiy fanlar va tillarni birlashtiradi.', '[]', ' - BSTU', 'Fakultet raqamli universitet muhitida iqtisodiyot, menejment, turizm, AKT, avtomatlashtirish, aniq fanlar, ijtimoiy fanlar va tillarni birlashtiradi.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(7, 2, 'ru', 'Факультет сервиса и цифровизации', 'Сервис и цифровизация', 'Факультет объединяет экономику, менеджмент, туризм, ИКТ, автоматизацию, точные науки, социальные науки и языковое образование в цифровой университетской среде.', '[]', ' - BSTU', 'Факультет объединяет экономику, менеджмент, туризм, ИКТ, автоматизацию, точные науки, социальные науки и языковое образование в цифровой университетской среде.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(8, 2, 'ar', 'كلية الخدمات والرقمنة', 'الخدمات والرقمنة', 'تجمع الكلية بين الاقتصاد والإدارة والسياحة وتقنيات المعلومات والأتمتة والعلوم الدقيقة والاجتماعية وتعليم اللغات ضمن بيئة جامعية رقمية.', '[]', ' - BSTU', 'تجمع الكلية بين الاقتصاد والإدارة والسياحة وتقنيات المعلومات والأتمتة والعلوم الدقيقة والاجتماعية وتعليم اللغات ضمن بيئة جامعية رقمية.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(9, 3, 'en', 'Faculty of Natural Resources Management', 'Natural Resources', 'The faculty prepares engineers for water management, land cadastre, ecology, hydrogeology, vehicle engineering, geodesy and environmental protection.', '[]', ' - BSTU', 'The faculty prepares engineers for water management, land cadastre, ecology, hydrogeology, vehicle engineering, geodesy and environmental protection.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(10, 3, 'uz', 'Tabiiy resurslarni boshqarish fakulteti', 'Tabiiy resurslar', 'Fakultet suv xo‘jaligi, yer kadastri, ekologiya, gidrogeologiya, transport muhandisligi, geodeziya va atrof-muhit muhofazasi bo‘yicha muhandislar tayyorlaydi.', '[]', ' - BSTU', 'Fakultet suv xo‘jaligi, yer kadastri, ekologiya, gidrogeologiya, transport muhandisligi, geodeziya va atrof-muhit muhofazasi bo‘yicha muhandislar tayyorlaydi.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(11, 3, 'ru', 'Факультет управления природными ресурсами', 'Природные ресурсы', 'Факультет готовит инженеров по водному хозяйству, земельному кадастру, экологии, гидрогеологии, транспортной инженерии, геодезии и охране окружающей среды.', '[]', ' - BSTU', 'Факультет готовит инженеров по водному хозяйству, земельному кадастру, экологии, гидрогеологии, транспортной инженерии, геодезии и охране окружающей среды.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(12, 3, 'ar', 'كلية إدارة الموارد الطبيعية', 'الموارد الطبيعية', 'تعد الكلية مهندسين في إدارة المياه والسجل العقاري والبيئة والهيدروجيولوجيا وهندسة المركبات والجيوديسيا وحماية البيئة.', '[]', ' - BSTU', 'تعد الكلية مهندسين في إدارة المياه والسجل العقاري والبيئة والهيدروجيولوجيا وهندسة المركبات والجيوديسيا وحماية البيئة.', '2026-07-26 00:16:43', '2026-07-27 06:31:33'),
(13, 4, 'en', 'Faculty of Engineering', 'Engineering', 'Power engineering, architecture, infrastructure design, mechanics, and textile materials science.', NULL, ' - BSTU', 'Power engineering, architecture, infrastructure design, mechanics, and textile materials science.', '2026-07-27 06:31:33', '2026-07-27 06:31:33'),
(14, 4, 'uz', 'Muhandislik fakulteti', 'Muhandislik fakulteti', 'Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.', NULL, ' - BSTU', 'Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.', '2026-07-27 06:31:33', '2026-07-27 06:31:33'),
(15, 4, 'ru', 'Инженерный факультет', 'Инженерный факультет', 'Электроэнергетика, архитектура, строительная инженерия, дизайн легкой промышленности и механика.', NULL, ' - BSTU', 'Электроэнергетика, архитектура, строительная инженерия, дизайн легкой промышленности и механика.', '2026-07-27 06:31:33', '2026-07-27 06:31:33'),
(16, 4, 'ar', 'كلية الهندسة', 'كلية الهندسة', 'هندسة الطاقة، الهندسة المعمارية، الهندسة المدنية، وتصميم الصناعات الخفيفة والمنسوجات والميكانيكا.', NULL, ' - BSTU', 'هندسة الطاقة، الهندسة المعمارية، الهندسة المدنية، وتصميم الصناعات الخفيفة والمنسوجات والميكانيكا.', '2026-07-27 06:31:33', '2026-07-27 06:31:33');
