INSERT INTO `page_block_translations` (`id`, `page_block_id`, `locale`, `title`, `subtitle`, `content`, `button_text`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'Shape Your Future with Bukhara State Technical University', 'Fostering academic excellence, scientific research, and technological innovation in engineering and natural resources management.', 'Admissions open for Fall 2026', 'Apply Now', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(2, 1, 'uz', 'Kelajagingizni Buxoro davlat texnika universiteti bilan yarating', 'Muhandislik va tabiiy resurslarni boshqarish sohalarida akademik mukammallik, ilmiy tadqiqot va texnologik innovatsiyalarni rivojlantiramiz.', 'Admissions open for Fall 2026', 'Hujjat topshirish', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(3, 1, 'ru', 'Создайте свое будущее с Бухарским государственным техническим университетом', 'Мы развиваем академическое качество, научные исследования и технологические инновации в инженерии и управлении природными ресурсами.', 'Admissions open for Fall 2026', 'Подать заявку', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(4, 1, 'ar', 'اصنع مستقبلك مع جامعة بخارى الحكومية التقنية', 'نعزز التميز الأكاديمي والبحث العلمي والابتكار التقني في الهندسة وإدارة الموارد الطبيعية.', 'Admissions open for Fall 2026', 'تقدم الآن', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(5, 2, 'en', 'Transforming Technical Education for the Global Era', 'Rector\'s Address', 'Welcome message from the Rector.', 'View Structure', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(6, 2, 'uz', 'Global davr uchun texnik ta\'limni transformatsiya qilish', 'Rector murojaati', 'Welcome message from the Rector.', 'View Structure', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(7, 2, 'ru', 'Трансформация технического образования для глобальной эпохи', 'Обращение ректора', 'Welcome message from the Rector.', 'View Structure', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(8, 2, 'ar', 'تحويل التعليم التقني لمواكبة العصر العالمي الجديد', 'كلمة رئيسة الجامعة', 'Welcome message from the Rector.', 'View Structure', '2026-07-15 19:25:34', '2026-07-15 19:25:34'),
(9, 3, 'en', 'Green Campus Leadership in Sustainability', 'Sustainability', 'Explore All Green Campus Initiatives', 'Read More', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(10, 3, 'uz', 'Green Campus Leadership in Sustainability', 'Sustainability', 'Explore All Green Campus Initiatives', 'Read More', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(11, 3, 'ru', 'Green Campus Leadership in Sustainability', 'Sustainability', 'Explore All Green Campus Initiatives', 'Read More', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(12, 3, 'ar', 'Green Campus Leadership in Sustainability', 'Sustainability', 'Explore All Green Campus Initiatives', 'Read More', '2026-07-16 00:25:34', '2026-07-16 00:25:34');
