INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `content`, `action_label`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'HEMIS Student Portal', 'Access your academic schedule, grades, course registration, and attendance records.', 'The dormitory is located just a 5-minute walk from academic buildings. Rooms are shared by 2 students. Security guards are active 24/7. Fees are paid per semester.', 'Login to HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37'),
(2, 1, 'uz', 'HEMIS talabalar portali', 'Dars jadvali, baholar, fanlarga ro‘yxatdan o‘tish va davomat ma’lumotlarini ko‘ring.', 'Talabalar turar joyi o‘quv binolaridan 5 daqiqalik masofada joylashgan. Xonalar 2 kishilik. Xavfsizlik xizmati 24/7 ishlaydi. To‘lovlar har semestrda amalga oshiriladi.', 'HEMISga kirish', '2026-07-21 05:44:39', '2026-07-21 06:27:37'),
(3, 1, 'ru', 'Студенческий портал HEMIS', 'Просматривайте расписание, оценки, регистрацию на курсы и данные посещаемости.', 'Общежитие расположено всего в 5 минутах ходьбы от учебных корпусов. Комнаты рассчитаны на 2 студентов. Круглосуточная охрана. Оплата производится за семестр.', 'Войти в HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37'),
(4, 1, 'ar', 'بوابة الطالب HEMIS', 'يمكنك الوصول إلى جدولك الأكاديمي والدرجات وتسجيل المقررات وسجلات الحضور.', 'يقع السكن الجامعي على بعد 5 دقائق فقط سيرًا على الأقدام من المباني الأكاديمية. الغرف مشتركة لطالبين. الحراس الأمنيون متواجدون 24/7. تُدفع الرسوم لكل فصل دراسي.', 'تسجيل الدخول إلى HEMIS', '2026-07-21 05:44:39', '2026-07-21 06:27:37'),
(5, 2, 'en', 'Office of the Registrar', 'Manage your academic records, requests, official transcripts, and enrollment certificates.', 'Comprehensive laboratory research and academic training in food safety, industrial chemical engineering, and organic compounds.', 'Access Registrar Office', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(6, 2, 'uz', 'Registrator ofisi', 'Akademik yozuvlar, so‘rovlar, rasmiy transkriptlar va o‘qishga qabul sertifikatlarini boshqaring.', 'Oziq-ovqat xavfsizligi, sanoat kimyo muhandisligi va organik birikmalar bo‘yicha keng qamrovli laboratoriya tadqiqotlari va akademik tayyorgarlik.', 'Registrator ofisiga kirish', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(7, 2, 'ru', 'Офис регистратора', 'Управляйте академическими записями, запросами, официальными транскриптами и справками о зачислении.', 'Комплексные лабораторные исследования и академическая подготовка в области безопасности пищевых продуктов, промышленной химической инженерии и органических соединений.', 'офис регистратора', '2026-07-21 05:44:39', '2026-07-23 00:30:16'),
(8, 2, 'ar', 'مكتب المسجل', 'إدارة السجلات الأكاديمية والطلبات والكشوف الرسمية وشهادات القيد.', 'أبحاث مخبرية شاملة وتدريب أكاديمي في مجال سلامة الأغذية، والهندسة الكيميائية الصناعية، والمركبات العضوية.', 'الدخول إلى مكتب المسجل', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(9, 3, 'en', 'Distance Learning Platform', 'Join online lectures, access electronic learning resources, and participate in discussion forums.', 'Providing engineering expertise and research on upstream and downstream operations, hydrocarbon transportation, and well development.', 'Open Moodle Platform', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(10, 3, 'uz', 'Masofaviy ta’lim platformasi', 'Onlayn ma’ruzalarga qo‘shiling, elektron o‘quv resurslaridan foydalaning va forumlarda qatnashing.', 'Neft va gaz qazib olish hamda qayta ishlash operatsiyalari, uglevodorodlarni tashish va quduqlarni o‘zlashtirish bo‘yicha muhandislik tajribasi va tadqiqotlar.', 'Moodle platformasini ochish', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(11, 3, 'ru', 'Платформа дистанционного обучения', 'Подключайтесь к онлайн-лекциям, используйте электронные ресурсы и участвуйте в форумах.', 'Предоставление инженерного опыта и исследований в области добычи и переработки углеводородов, их транспортировки и разработки скважин.', 'Открыть Moodle', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(12, 3, 'ar', 'منصة التعليم عن بُعد', 'انضم إلى المحاضرات عبر الإنترنت، واستخدم الموارد التعليمية الإلكترونية، وشارك في المنتديات.', 'تقديم الخبرة الهندسية والأبحاث في عمليات المنبع والمصب، ونقل الهيدروكربونات، وتطوير الآبار.', 'فتح منصة Moodle', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(13, 4, 'en', 'Contract & Invoice Portal', 'Generate your student tuition contract invoice, check payment status, and make online payments.', 'Training in computer-aided structural design, modern architecture, geotechnical engineering, and seismic resilience standards.', 'Get Tuition Invoice', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(14, 4, 'uz', 'Shartnoma va hisob-faktura portali', 'Talabalik kontrakt hisobini yarating, to‘lov holatini tekshiring va onlayn to‘lov qiling.', 'Kompyuter yordamida qurilishni loyihalash, zamonaviy arxitektura, geotexnik muhandislik va seysmik chidamlilik standartlari bo‘yicha o‘qitish.', 'To‘lov hisobini olish', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(15, 4, 'ru', 'Портал договоров и счетов', 'Сформируйте счет по контракту, проверьте статус оплаты и выполните онлайн-платеж.', 'Обучение компьютерному проектированию строительных конструкций, современной архитектуре, геотехнической инженерии и стандартам сейсмостойкости.', 'Получить счет за обучение', '2026-07-21 05:44:39', '2026-07-21 06:27:38'),
(16, 4, 'ar', 'بوابة العقود والفواتير', 'أنشئ فاتورة عقد الرسوم الدراسية، وتحقق من حالة الدفع، وقم بالدفع عبر الإنترنت.', 'التدريب على التصميم الهيكلي بمساعدة الحاسوب، الهندسة المعمارية الحديثة، الهندسة الجيوتقنية، ومعايير مقاومة الزلازل.', 'الحصول على فاتورة الرسوم', '2026-07-21 05:44:39', '2026-07-21 06:27:39'),
(17, 5, 'en', 'Remote Education Management', 'Manage distance learning workflows, online learning assignments, and academic coordination tools.', 'Modern education in software engineering, database management, smart power grid monitoring, and solar energy installations.', 'Open Remote Platform', '2026-07-21 06:04:30', '2026-07-21 06:27:39'),
(18, 5, 'uz', 'Masofaviy ta’lim boshqaruvi', 'Masofaviy ta’lim jarayonlari, onlayn topshiriqlar va akademik muvofiqlashtirish vositalarini boshqaring.', 'Dasturiy ta‘minot muhandisligi, ma‘lumotlar bazasini boshqarish, aqlli energiya tarmoqlarini monitoring qilish va quyosh energiyasi qurilmalari bo‘yicha zamonaviy ta‘lim.', 'Masofaviy platformani ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:39'),
(19, 5, 'ru', 'Управление дистанционным обучением', 'Управляйте процессами дистанционного обучения, онлайн-заданиями и академической координацией.', 'Современное образование в области программной инженерии, управления базами данных, мониторинга интеллектуальных энергосетей и солнечных энергоустановок.', 'Открыть платформу', '2026-07-21 06:04:30', '2026-07-21 06:27:39'),
(20, 5, 'ar', 'إدارة التعليم عن بُعد', 'إدارة مسارات التعليم عن بُعد والمهام الإلكترونية وأدوات التنسيق الأكاديمي.', 'تعليم حديث في هندسة البرمجيات، إدارة قواعد البيانات، مراقبة شبكات الطاقة الذكية، وتركيبات الطاقة الشمسية.', 'فتح منصة التعليم عن بُعد', '2026-07-21 06:04:30', '2026-07-21 06:27:39'),
(21, 6, 'en', 'Anti-Corruption Hotline', 'Report corruption risks and ethics concerns through the official confidential university channel.', 'Specialized research in raw cotton processing, spinning technologies, garment design, transport logistics, and logistics auditing.', 'Open Telegram Bot', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(22, 6, 'uz', 'Korrupsiyaga qarshi aloqa kanali', 'Korrupsiya xavflari va odob-axloq masalalari haqida rasmiy maxfiy kanal orqali xabar bering.', 'Paxta xomashyosini qayta ishlash, yigirish texnologiyalari, kiyim-kechak dizayni, transport logistikasi va logistika auditi sohasida ixtisoslashtirilgan tadqiqotlar.', 'Telegram botni ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(23, 6, 'ru', 'Антикоррупционный канал', 'Сообщайте о коррупционных рисках и вопросах этики через официальный конфиденциальный канал университета.', 'Специализированные исследования в области переработки хлопка-сырца, прядильных технологий, дизайна одежды, транспортной логистики и логистического аудита.', 'Открыть Telegram-бот', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(24, 6, 'ar', 'قناة مكافحة الفساد', 'أبلغ عن مخاطر الفساد والمخاوف الأخلاقية عبر القناة الجامعية الرسمية بسرية.', 'أبحاث متخصصة في معالجة القطن الخام، وتقنيات الغزل، وتصميم الملابس، ولوجستيات النقل، وتدقيق الخدمات اللوجستية.', 'فتح بوت Telegram', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(25, 7, 'en', 'Student Accommodation Portal', 'Apply for dormitory accommodation, track housing requests, and access residence information.', 'Advanced scientific research on water resource conservation, eco-friendly farming practices, and soil erosion prevention.', 'Open Accommodation Portal', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(26, 7, 'uz', 'Talabalar turar joyi portali', 'Yotoqxona uchun ariza yuboring, joylashuv so‘rovlarini kuzating va turar joy ma’lumotlarini oling.', 'Suv resurslarini tejash, ekologik toza dehqonchilik amaliyoti va tuproq eroziyasini oldini olish bo‘yicha ilg‘or ilmiy tadqiqotlar.', 'Turar joy portalini ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(27, 7, 'ru', 'Портал студенческого проживания', 'Подавайте заявки на общежитие, отслеживайте запросы и получайте информацию о проживании.', 'Передовые научные исследования в области сохранения водных ресурсов, экологически чистых методов ведения сельского хозяйства и предотвращения эрозии почв.', 'Открыть портал проживания', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(28, 7, 'ar', 'بوابة سكن الطلاب', 'قدّم طلب السكن الجامعي، وتابع طلبات الإقامة، واطلع على معلومات السكن.', 'أبحاث علمية متقدمة في مجال الحفاظ على الموارد المائية، والممارسات الزراعية الصديقة للبيئة، ومنع انجراف التربة.', 'فتح بوابة السكن', '2026-07-21 06:04:30', '2026-07-21 06:27:40'),
(29, 8, 'en', 'Academic Timetable', 'View class schedules, academic rooms, weekly timetables, and teaching session updates.', NULL, 'View Timetable', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(30, 8, 'uz', 'Akademik dars jadvali', 'Dars jadvali, auditoriyalar, haftalik reja va mashg‘ulot yangilanishlarini ko‘ring.', NULL, 'Jadvalni ko‘rish', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(31, 8, 'ru', 'Академическое расписание', 'Просматривайте расписание занятий, аудитории, недельные планы и обновления учебных сессий.', NULL, 'Открыть расписание', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(32, 8, 'ar', 'الجدول الأكاديمي', 'اعرض جداول المحاضرات والقاعات والخطط الأسبوعية وتحديثات الحصص الدراسية.', NULL, 'عرض الجدول', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(33, 9, 'en', 'Online Payment System', 'Pay tuition, dormitory fees, library fines, and other university charges securely online.', NULL, 'Make Payment', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(34, 9, 'uz', 'Onlayn to‘lov tizimi', 'Kontrakt, yotoqxona, kutubxona va boshqa universitet to‘lovlarini xavfsiz onlayn amalga oshiring.', NULL, 'To‘lov qilish', '2026-07-21 06:04:30', '2026-07-21 06:27:41'),
(35, 9, 'ru', 'Система онлайн-оплаты', 'Безопасно оплачивайте обучение, общежитие, библиотечные штрафы и другие университетские услуги.', NULL, 'Оплатить онлайн', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(36, 9, 'ar', 'نظام الدفع الإلكتروني', 'ادفع الرسوم الدراسية والسكن والغرامات والخدمات الجامعية الأخرى بأمان عبر الإنترنت.', NULL, 'إجراء الدفع', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(37, 10, 'en', 'HEMIS Teacher Portal', 'Faculty members can manage classes, gradebooks, attendance, and academic reports.', NULL, 'Login to HEMIS', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(38, 10, 'uz', 'HEMIS o‘qituvchilar portali', 'Professor-o‘qituvchilar darslar, baholash jurnali, davomat va akademik hisobotlarni boshqaradi.', NULL, 'HEMISga kirish', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(39, 10, 'ru', 'Портал преподавателей HEMIS', 'Преподаватели могут управлять занятиями, журналами оценок, посещаемостью и отчетами.', NULL, 'Войти в HEMIS', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(40, 10, 'ar', 'بوابة أعضاء هيئة التدريس HEMIS', 'يمكن لأعضاء هيئة التدريس إدارة المقررات وسجلات الدرجات والحضور والتقارير الأكاديمية.', NULL, 'تسجيل الدخول إلى HEMIS', '2026-07-21 06:04:30', '2026-07-21 06:27:42'),
(41, 11, 'en', 'Digital Library', 'Search electronic books, research materials, academic publications, and library resources.', NULL, 'Open Library', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(42, 11, 'uz', 'Raqamli kutubxona', 'Elektron kitoblar, ilmiy materiallar, akademik nashrlar va kutubxona resurslarini qidiring.', NULL, 'Kutubxonani ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(43, 11, 'ru', 'Цифровая библиотека', 'Ищите электронные книги, научные материалы, академические публикации и ресурсы библиотеки.', NULL, 'Открыть библиотеку', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(44, 11, 'ar', 'المكتبة الرقمية', 'ابحث في الكتب الإلكترونية والمواد البحثية والمنشورات الأكاديمية وموارد المكتبة.', NULL, 'فتح المكتبة', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(45, 12, 'en', 'Dissertations Platform', 'Access dissertation announcements, research defense materials, and scientific council information.', NULL, 'View Dissertations', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(46, 12, 'uz', 'Dissertatsiyalar platformasi', 'Dissertatsiya e’lonlari, himoya materiallari va ilmiy kengash ma’lumotlaridan foydalaning.', NULL, 'Dissertatsiyalarni ko‘rish', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(47, 12, 'ru', 'Платформа диссертаций', 'Получайте доступ к объявлениям о диссертациях, материалам защит и информации научного совета.', NULL, 'Смотреть диссертации', '2026-07-21 06:04:30', '2026-07-21 06:27:43'),
(48, 12, 'ar', 'منصة الرسائل العلمية', 'اطلع على إعلانات الرسائل ومواد المناقشات ومعلومات المجالس العلمية.', NULL, 'عرض الرسائل العلمية', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(49, 13, 'en', 'Scientific Conferences', 'Register for conferences, submit papers, and follow university scientific events.', NULL, 'Open Conferences', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(50, 13, 'uz', 'Ilmiy konferensiyalar', 'Konferensiyalarga ro‘yxatdan o‘ting, maqola yuboring va universitet ilmiy tadbirlarini kuzating.', NULL, 'Konferensiyalarni ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(51, 13, 'ru', 'Научные конференции', 'Регистрируйтесь на конференции, отправляйте статьи и следите за научными событиями университета.', NULL, 'Открыть конференции', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(52, 13, 'ar', 'المؤتمرات العلمية', 'سجّل في المؤتمرات، وقدّم الأبحاث، وتابع الفعاليات العلمية في الجامعة.', NULL, 'فتح المؤتمرات', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(53, 14, 'en', 'Virtual Campus Tour', 'Explore BSTU buildings, laboratories, campus spaces, and student facilities online.', NULL, 'Start Virtual Tour', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(54, 14, 'uz', 'Virtual kampus sayohati', 'BuxDTU binolari, laboratoriyalari, kampus hududi va talabalar infratuzilmasini onlayn ko‘ring.', NULL, 'Virtual sayohatni boshlash', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(55, 14, 'ru', 'Виртуальный тур по кампусу', 'Исследуйте здания, лаборатории, территорию кампуса и студенческую инфраструктуру онлайн.', NULL, 'Начать виртуальный тур', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(56, 14, 'ar', 'جولة افتراضية في الحرم الجامعي', 'استكشف مباني BSTU والمختبرات ومساحات الحرم ومرافق الطلاب عبر الإنترنت.', NULL, 'بدء الجولة الافتراضية', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(57, 15, 'en', 'KPI Monitoring System', 'Track performance indicators, departmental progress, and institutional reporting metrics.', NULL, 'Open KPI System', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(58, 15, 'uz', 'KPI monitoring tizimi', 'Samaradorlik ko‘rsatkichlari, bo‘limlar rivoji va institutsional hisobot metrikalarini kuzating.', NULL, 'KPI tizimini ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(59, 15, 'ru', 'Система мониторинга KPI', 'Отслеживайте показатели эффективности, прогресс подразделений и отчетные метрики.', NULL, 'Открыть KPI', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(60, 15, 'ar', 'نظام متابعة مؤشرات الأداء', 'تابع مؤشرات الأداء وتقدم الأقسام ومقاييس التقارير المؤسسية.', NULL, 'فتح نظام KPI', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(61, 16, 'en', 'Official Telegram Channel', 'Follow official university updates, urgent notices, student news, and campus announcements.', NULL, 'Open Telegram', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(62, 16, 'uz', 'Rasmiy Telegram kanali', 'Universitet yangiliklari, muhim xabarlar, talabalar e’lonlari va kampus ma’lumotlarini kuzating.', NULL, 'Telegramni ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(63, 16, 'ru', 'Официальный Telegram-канал', 'Следите за новостями университета, срочными уведомлениями и объявлениями кампуса.', NULL, 'Открыть Telegram', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(64, 16, 'ar', 'قناة Telegram الرسمية', 'تابع تحديثات الجامعة الرسمية والتنبيهات العاجلة وأخبار الطلاب وإعلانات الحرم الجامعي.', NULL, 'فتح Telegram', '2026-07-21 06:04:30', '2026-07-21 06:27:44'),
(65, 17, 'en', 'University Webmail', 'Access official university email accounts for staff, departments, and academic communication.', NULL, 'Open Webmail', '2026-07-21 06:04:30', '2026-07-21 06:27:45'),
(66, 17, 'uz', 'Universitet veb-pochtasi', 'Xodimlar, bo‘limlar va akademik aloqa uchun rasmiy universitet email hisoblariga kiring.', NULL, 'Veb-pochtani ochish', '2026-07-21 06:04:30', '2026-07-21 06:27:45'),
(67, 17, 'ru', 'Университетская веб-почта', 'Откройте официальные почтовые аккаунты университета для сотрудников и подразделений.', NULL, 'Открыть Webmail', '2026-07-21 06:04:30', '2026-07-21 06:27:46'),
(68, 17, 'ar', 'البريد الإلكتروني الجامعي', 'ادخل إلى حسابات البريد الرسمية للموظفين والأقسام والتواصل الأكاديمي.', NULL, 'فتح البريد الجامعي', '2026-07-21 06:04:30', '2026-07-21 06:27:46');
