(38, 'pdf.shared.ministry', 'MINISTRY OF HIGHER EDUCATION, SCIENCE AND INNOVATIONS OF THE REPUBLIC OF UZBEKISTAN', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(39, 'pdf.shared.university', 'BUKHARA STATE TECHNICAL UNIVERSITY', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(40, 'pdf.shared.address', '15 K. Murtazoyev Street, Bukhara city, Republic of Uzbekistan', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(41, 'pdf.shared.stamp', 'Official stamp and signature', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(42, 'pdf.shared.generated_footer', 'This document is generated by the university international student system.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(43, 'pdf.admission.title', 'ADMISSION LETTER', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(44, 'pdf.admission.subtitle', 'Offer of Enrollment for International Student', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(45, 'pdf.admission.body', 'The student has submitted documents for studying at Bukhara State Technical University (Buxoro davlat texnika universiteti) in the Republic of Uzbekistan and has received an offer of enrollment in <b>{{program}}</b> program. The student will begin studies in the <b>{{academic_year}}</b> academic year at the first level <b>{{study_language}}-medium</b> program. The student must submit his/her original documents after arriving in the country.<br><br>The Ministry of Higher Education of the Republic of Uzbekistan recognizes Bukhara State Technical University (Buxoro davlat texnika universiteti). The university is listed in the Times Higher Education, QS World Rankings Asia 2025, UI GreenMetric World University Rankings.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(46, 'pdf.admission.signature', 'Rector / Authorized Representative', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(47, 'pdf.admission.footer', 'This admission letter is generated by the university international admissions system. It is valid together with the applicant passport and original education documents.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(48, 'pdf.enrollment.title', 'ENROLLMENT CERTIFICATE', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(49, 'pdf.enrollment.subtitle', 'Student Registration Confirmation', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(50, 'pdf.enrollment.body', 'This is to certify that <b>{{name}}</b> has been enrolled as an international student of Bukhara State Technical University (Buxoro davlat texnika universiteti) for the <b>{{academic_year}}</b> academic year after receiving admission and completing the required initial contract payment. The student is registered in the <b>{{program}}</b> program.<br><br>This certificate is issued for submission to the relevant authorities and confirms the student registration status at the university as of the issue date above.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(51, 'pdf.enrollment.signature', 'Registrar / Authorized Representative', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(52, 'pdf.enrollment.footer', 'This document is generated by the university international student system.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(53, 'pdf.prikaz.title', 'ORDER OF ENROLLMENT', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(54, 'pdf.prikaz.subtitle', '', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(55, 'pdf.prikaz.body', 'Based on the submitted documents, issued admission letter, completed contract advance payment, and enrollment certificate, the student named above is included in the university enrollment order for international students of Bukhara State Technical University.<br><br>This document is issued for internal university registration and for the student subsequent telex, visa, housing, and residence permit procedures where applicable.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(56, 'pdf.prikaz.signature', 'Rector / Authorized Representative', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(57, 'pdf.prikaz.footer', '', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(58, 'pdf.study_contract.title', 'STUDY CONTRACT', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(59, 'pdf.study_contract.subtitle', '', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(60, 'pdf.study_contract.body', 'This study contract confirms the financial terms for the international student listed above. The student must pay the required advance payment before the university issues the enrollment certificate and proceeds with the following registration stages. This contract is not a visa, residence permit, or final government registration document.<br><br>The remaining contract balance, service fees, residence, housing, telex, and visa-related procedures are processed according to the university rules and the official requirements of the Republic of Uzbekistan.', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(61, 'pdf.study_contract.signature', 'Authorized Representative', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
(62, 'pdf.study_contract.footer', '', 'text', 'pdf', 0, '2026-07-27 07:13:12', '2026-07-27 07:53:19'),
