(28, 7, 'ar', 'القسم التعليمي والمنهجي', 'عزيز خوجييف خولمرودوفيتش', 'رئيس القسم التعليمي والمنهجي', NULL, 'الخميس - السبت (09:00 - 13:00)', 'يدير العمل التعليمي بالجامعة وينظم العملية التدريسية وفق المناهج والخطط المعتمدة من وزارة التعليم العالي والعلوم والابتكارات، ويتابع تنفيذ الأعباء التدريسية للأساتذة.', '[\"\\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0644\\u062c\\u0645\\u064a\\u0639 \\u0623\\u0646\\u0634\\u0637\\u0629 \\u0648\\u0645\\u0648\\u0638\\u0641\\u064a \\u0627\\u0644\\u0642\\u0633\\u0645\\u061b\",\"\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a \\u0648\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633\\u064a\\u0629 \\u0648\\u0641\\u0642\\u0627\\u064b \\u0644\\u0644\\u0645\\u0646\\u0627\\u0647\\u062c \\u0648\\u0627\\u0644\\u062e\\u0637\\u0637 \\u0627\\u0644\\u0645\\u0642\\u0631\\u0629\\u061b\",\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0648\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u062e\\u0637\\u0637 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0627\\u0647\\u062c \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u064a\\u0629\\u061b\",\"\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0644\\u064a\\u0628 \\u0627\\u0644\\u062d\\u062f\\u064a\\u062b\\u0629 \\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0645\\u0639\\u0627\\u0631\\u0641 \\u0627\\u0644\\u0637\\u0644\\u0627\\u0628 \\u0648\\u0645\\u0647\\u0627\\u0631\\u0627\\u062a\\u0647\\u0645\\u061b\",\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u062a\\u0632\\u0627\\u0645 \\u0623\\u0639\\u0636\\u0627\\u0621 \\u0647\\u064a\\u0626\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633 \\u0628\\u062a\\u0646\\u0641\\u064a\\u0630 \\u0627\\u0644\\u0623\\u0639\\u0628\\u0627\\u0621 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633\\u064a\\u0629 \\u0627\\u0644\\u0633\\u0646\\u0648\\u064a\\u0629\\u061b\",\"\\u062f\\u0631\\u0627\\u0633\\u0629 \\u0648\\u062a\\u0639\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0645\\u0645\\u0627\\u0631\\u0633\\u0627\\u062a \\u0627\\u0644\\u0628\\u064a\\u062f\\u0627\\u063a\\u0648\\u062c\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629\\u061b\",\"\\u062a\\u0642\\u064a\\u064a\\u0645 \\u062a\\u0646\\u0638\\u064a\\u0645 \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0643\\u0644\\u064a\\u0627\\u062a \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u062a\\u0648\\u062c\\u064a\\u0647\\u0627\\u062a \\u0644\\u062a\\u0644\\u0627\\u0641\\u064a \\u0627\\u0644\\u0642\\u0635\\u0648\\u0631\\u061b\",\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0647\\u0646\\u064a \\u0648\\u0625\\u0643\\u0633\\u0627\\u0628 \\u0627\\u0644\\u062e\\u0628\\u0631\\u0629 \\u0644\\u0644\\u0645\\u062f\\u0631\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u061b\",\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0642\\u0627\\u0639\\u062f\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0634\\u0627\\u0645\\u0644\\u0629 \\u062d\\u0648\\u0644 \\u0623\\u0639\\u0636\\u0627\\u0621 \\u0647\\u064a\\u0626\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633 \\u0628\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629\\u061b\",\"\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u062e\\u0637\\u0637 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0648\\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631 \\u0644\\u0623\\u0639\\u0636\\u0627\\u0621 \\u0647\\u064a\\u0626\\u0629 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0633\\u061b\",\"\\u0627\\u0644\\u0645\\u0633\\u0627\\u0647\\u0645\\u0629 \\u0641\\u064a \\u062a\\u0648\\u062c\\u064a\\u0647 \\u0648\\u062a\\u0648\\u0638\\u064a\\u0641 \\u062e\\u0631\\u064a\\u062c\\u064a \\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u0627\\u0644\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0645\\u0639 \\u0627\\u0644\\u062c\\u0647\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0646\\u064a\\u0629\\u061b\",\"\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0648\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0645\\u064a\\u062f\\u0627\\u0646\\u064a \\u0648\\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a \\u0644\\u0644\\u0637\\u0644\\u0627\\u0628 \\u0648\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u062a\\u0646\\u0641\\u064a\\u0630\\u0647\\u0627\\u061b\",\"\\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0641\\u064a \\u0623\\u0639\\u0645\\u0627\\u0644 \\u0644\\u062c\\u0646\\u0629 \\u0627\\u0644\\u0642\\u0628\\u0648\\u0644 \\u0628\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0648\\u062a\\u062c\\u0645\\u064a\\u0639 \\u0648\\u062a\\u062d\\u0644\\u064a\\u0644 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0642\\u0628\\u0648\\u0644\\u061b\",\"\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0627\\u0644\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0633\\u0646\\u0648\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0643\\u0644\\u064a\\u0627\\u062a \\u0648\\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645 \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0645\\u0642\\u062a\\u0631\\u062d\\u0627\\u062a \\u0644\\u0644\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(29, 8, 'en', 'Master’s Department', 'To\'xtayeva Zebo Sharifovna', 'Head of the Master\'s Department', NULL, 'Monday - Saturday (09:00 - 16:00)', 'The admission of students to master\'s specialties at the university began in the 1999-2000 academic year. The educational process at the master\'s department is well organized, with main focus on the educational-methodological support of subjects and the material-technical base.', '[\"Direct supervision of educational-methodological, spiritual-enlightenment, and scientific-research activities within the department;\",\"Guiding master\'s students in conducting scientific research work and coordinating the research activities they undertake;\",\"Monitoring the quality organization of master\'s students\' internships, projects (works), master\'s theses, as well as their independent work;\",\"Developing and implementing programs and projects aimed at the development of the master\'s program based on the assigned tasks;\",\"Ensuring compliance with the Regulation on the Master\'s Program approved by the Cabinet of Ministers.\",\"Master\'s students are fully involved in the scientific research work of the respective departments, and they also work as lab assistants, heads of cabinets, and assistant lecturers.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(30, 8, 'uz', 'Magistratura bo\'limi', 'To\'xtayeva Zebo Sharifovna', 'Magistratura bo\'limi boshlig\'i', NULL, 'Dushanba – Shanba (09:00 – 16:00)', 'Magistratura bo\'limi universitetda magistrlar tayyorlash jarayonini muvofiqlashtiradi. U ilmiy-tadqiqot ishlari va o\'quv jarayoni integratsiyasini ta\'minlaydi.', '[\"Magistraturada o\'quv jarayonini tashkil etish;\",\"Magistrlik dissertatsiyalari mavzularini tasdiqlash;\",\"Ilmiy-pedagogik va ilmiy-tadqiqot amaliyotlarini o\'tkazish;\",\"Magistrlarni yakuniy attestatsiyadan o\'tkazish ishlarini muvofiqlashtirish.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(31, 8, 'ru', 'Отдел магистратуры', 'Тухтаева Зебо Шарифовна', 'Начальник отдела магистратуры', NULL, 'Понедельник - Суббота (09:00 - 16:00)', 'Организует учебный, научно-исследовательский и духовно-просветительский процесс по специальностям магистратуры. В настоящее время в магистратуре обучается 308 студентов по 25 специальностям.', '[\"\\u041d\\u0435\\u043f\\u043e\\u0441\\u0440\\u0435\\u0434\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0435 \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u043e \\u0443\\u0447\\u0435\\u0431\\u043d\\u043e\\u0439, \\u043c\\u0435\\u0442\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0438 \\u043d\\u0430\\u0443\\u0447\\u043d\\u043e\\u0439 \\u0434\\u0435\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u043e\\u0442\\u0434\\u0435\\u043b\\u0430;\",\"\\u0420\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u043e \\u043d\\u0430\\u0443\\u0447\\u043d\\u043e-\\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u0441\\u043a\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u043e\\u0439 \\u043c\\u0430\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u043d\\u0442\\u043e\\u0432 \\u0438 \\u043a\\u043e\\u043e\\u0440\\u0434\\u0438\\u043d\\u0430\\u0446\\u0438\\u044f \\u0438\\u0445 \\u043d\\u0430\\u0443\\u0447\\u043d\\u043e\\u0439 \\u0434\\u0435\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438;\",\"\\u041c\\u043e\\u043d\\u0438\\u0442\\u043e\\u0440\\u0438\\u043d\\u0433 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a \\u043c\\u0430\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u043d\\u0442\\u043e\\u0432, \\u0438\\u0445 \\u0434\\u0438\\u0441\\u0441\\u0435\\u0440\\u0442\\u0430\\u0446\\u0438\\u0439 \\u0438 \\u0441\\u0430\\u043c\\u043e\\u0441\\u0442\\u043e\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b;\",\"\\u0420\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 \\u0438 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c \\u0440\\u0430\\u0437\\u0432\\u0438\\u0442\\u0438\\u044f \\u043c\\u0430\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u0442\\u0443\\u0440\\u044b;\",\"\\u041e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0441\\u043e\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u044f \\u041f\\u043e\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u044f \\u043e \\u043c\\u0430\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u0442\\u0443\\u0440\\u0435, \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u041a\\u0430\\u0431\\u0438\\u043d\\u0435\\u0441\\u043a\\u043e\\u043c \\u041c\\u0438\\u043d\\u0438\\u0441\\u0442\\u0440\\u043e\\u0432;\",\"\\u041f\\u0440\\u0438\\u0432\\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043c\\u0430\\u0433\\u0438\\u0441\\u0442\\u0440\\u0430\\u043d\\u0442\\u043e\\u0432 \\u043a \\u043d\\u0430\\u0443\\u0447\\u043d\\u043e-\\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u0441\\u043a\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0435 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440 \\u0432 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435 \\u0430\\u0441\\u0441\\u0438\\u0441\\u0442\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438\\u043b\\u0438 \\u043b\\u0430\\u0431\\u043e\\u0440\\u0430\\u043d\\u0442\\u043e\\u0432.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(32, 8, 'ar', 'إدارة الدراسات العليا (الماجستير)', 'توختاييفا زيبو شريفوفنا', 'رئيسة قسم الماجستير', NULL, 'الاثنين - السبت (09:00 - 16:00)', 'تنظم وتنسق العملية التعليمية والبحثية لطلبة الماجستير في 25 تخصصاً أكاديمياً بالجامعة بالتوافق مع القرارات الحكومية المعتمدة. ويبلغ عدد المسجلين حالياً 308 طلاب.', '[\"\\u0627\\u0644\\u0625\\u0634\\u0631\\u0627\\u0641 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0646\\u0634\\u0637\\u0629 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0647\\u062c\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0628\\u062d\\u062b\\u064a\\u0629 \\u0644\\u0644\\u0642\\u0633\\u0645\\u061b\",\"\\u062a\\u0648\\u062c\\u064a\\u0647 \\u0637\\u0644\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0627\\u062c\\u0633\\u062a\\u064a\\u0631 \\u0641\\u064a \\u0628\\u062d\\u0648\\u062b\\u0647\\u0645 \\u0648\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0627\\u0644\\u0623\\u0646\\u0634\\u0637\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u064a\\u0634\\u0627\\u0631\\u0643\\u0648\\u0646 \\u0641\\u064a\\u0647\\u0627\\u061b\",\"\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u062c\\u0648\\u062f\\u0629 \\u062a\\u0646\\u0638\\u064a\\u0645 \\u062a\\u062f\\u0631\\u064a\\u0628\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u062c\\u0633\\u062a\\u064a\\u0631\\u060c \\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0627\\u0644\\u062a\\u062e\\u0631\\u062c\\u060c \\u0648\\u0627\\u0644\\u0631\\u0633\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a\\u0629\\u061b\",\"\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0648\\u0625\\u0639\\u062f\\u0627\\u062f \\u062e\\u0637\\u0637 \\u0648\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0644\\u062a\\u062d\\u062f\\u064a\\u062b \\u0648\\u062a\\u0648\\u0633\\u064a\\u0639 \\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u062f\\u0631\\u0627\\u0633\\u0627\\u062a \\u0627\\u0644\\u0639\\u0644\\u064a\\u0627\\u061b\",\"\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0627\\u0644\\u062a\\u0627\\u0645 \\u0645\\u0639 \\u0644\\u0648\\u0627\\u0626\\u062d \\u062f\\u0631\\u0627\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0627\\u062c\\u0633\\u062a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u0645\\u0646 \\u0645\\u062c\\u0644\\u0633 \\u0627\\u0644\\u0648\\u0632\\u0631\\u0627\\u0621\\u061b\",\"\\u0625\\u0634\\u0631\\u0627\\u0643 \\u0637\\u0644\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0627\\u062c\\u0633\\u062a\\u064a\\u0631 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0627\\u0644\\u0628\\u062d\\u062b\\u064a\\u0629 \\u0644\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645 \\u0648\\u062a\\u0648\\u0641\\u064a\\u0631 \\u0641\\u0631\\u0635 \\u062a\\u062f\\u0631\\u064a\\u0633\\u064a\\u0629 \\u0644\\u0647\\u0645.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(33, 9, 'en', 'Department of Youth Affairs, Spirituality, and Enlightenment', '-', 'Director of Youth Affairs, Spirituality, and Enlightenment Department', NULL, 'Monday - Friday (09:00 to 17:00)', 'The main task of the Department of Youth Affairs, Spirituality, and Enlightenment at the institute is to convey all the teachings of our President regarding spirituality, enlightenment, and national ideology to the youth. The main goal is to nurture students in the spirit of loyalty to national and universal values.', '[\"Forming students into true citizens of the independent Republic of Uzbekistan based on national and universal values;\",\"Preparing students to sincerely fulfill their civic and filial duties towards the Motherland; increasing students\\u2019 sense of responsibility in mastering their professions;\",\"Developing and improving the individual qualities of students as unique personalities; promoting students\\u2019 social activity, initiative, and sense of social responsibility;\",\"Developing students\\u2019 socio-political and legal consciousness, and expanding their critical and analytical thinking skills;\",\"Educating students about the consequences of negative traits such as injustice, bribery, and localism;\",\"Organizing students\\u2019 leisure time meaningfully and supporting their scientific and creative activities based on their interests;\",\"Improving targeted spiritual, moral, and educational work.\",\"Establishing moral, aesthetic, political, legal, and artistic education among student youth;\",\"Organizing conferences, round tables, and meetings dedicated to promoting national customs and values;\",\"Forming ideological immunity in students against religious extremism, terrorism, drug addiction, and organized crime;\",\"Increasing youth interest in music, painting, literature, theater, and other arts, and promoting reading culture among them.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(34, 9, 'uz', 'Yoshlar bilan ishlash, ma\'naviyat va ma\'rifat bo\'limi', '-', 'Ma\'naviyat va ma\'rifat bo\'limi boshlig\'i', NULL, 'Dushanba – Shanba (09:00 – 16:00)', 'Bo\'lim talaba-yoshlar o\'rtasida ma\'naviy-ma\'rifiy ishlarni tashkil etadi, ularning bo\'sh vaqtlarini mazmunli o\'tkazish choralarini ko\'radi.', '[\"Talabalar o\'rtasida vatanparvarlik va ma\'naviy qadriyatlarni targ\'ib qilish;\",\"Turli tanlovlar, festivallar va uchrashuvlar tashkil etish;\",\"Talabalar yotoqxonalarida ma\'naviy tadbirlar o\'tkazish;\",\"Yoshlarni yot g\'oyalar ta\'siridan himoya qilish ishlarini olib borish.\"]', '2026-07-24 10:30:43', '2026-07-24 10:30:43'),
(35, 9, 'ru', 'Отдел по работе с молодежью, духовности и просвещения', '-', 'Начальник отдела духовности и просвещения', NULL, 'Понедельник - Пятница (с 09:00 до 17:00)', 'Главной задачей отдела является воспитание студентов в духе патриотизма, верности национальным ценностям, развитие их духовно-просветительского мировоззрения и содержательная организация досуга.', '[\"\\u0412\\u043e\\u0441\\u043f\\u0438\\u0442\\u0430\\u043d\\u0438\\u0435 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0432 \\u0434\\u0443\\u0445\\u0435 \\u0432\\u0435\\u0440\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043d\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u0438 \\u043e\\u0431\\u0449\\u0435\\u0447\\u0435\\u043b\\u043e\\u0432\\u0435\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c \\u0446\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044f\\u043c;\",\"\\u041f\\u043e\\u0434\\u0433\\u043e\\u0442\\u043e\\u0432\\u043a\\u0430 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043a \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044e \\u0441\\u0432\\u043e\\u0435\\u0433\\u043e \\u0433\\u0440\\u0430\\u0436\\u0434\\u0430\\u043d\\u0441\\u043a\\u043e\\u0433\\u043e \\u0438 \\u0441\\u044b\\u043d\\u043e\\u0432\\u043d\\u0435\\u0433\\u043e \\u0434\\u043e\\u043b\\u0433\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0434 \\u0420\\u043e\\u0434\\u0438\\u043d\\u043e\\u0439;\",\"\\u041f\\u043e\\u0432\\u044b\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0430 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0437\\u0430 \\u043e\\u0432\\u043b\\u0430\\u0434\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u0435\\u0439;\",\"\\u0420\\u0430\\u0437\\u0432\\u0438\\u0442\\u0438\\u0435 \\u0441\\u043e\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e-\\u043f\\u043e\\u043b\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0438 \\u043f\\u0440\\u0430\\u0432\\u043e\\u0432\\u043e\\u0433\\u043e \\u0441\\u043e\\u0437\\u043d\\u0430\\u043d\\u0438\\u044f \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432;\",\"\\u0420\\u0430\\u0437\\u044a\\u044f\\u0441\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435\\u0434\\u043e\\u043f\\u0443\\u0441\\u0442\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u043a\\u043e\\u0440\\u0440\\u0443\\u043f\\u0446\\u0438\\u0438 \\u0438 \\u043d\\u0430\\u0440\\u0443\\u0448\\u0435\\u043d\\u0438\\u0439 \\u044d\\u0442\\u0438\\u043a\\u0438;\",\"\\u041e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u0441\\u0443\\u0433\\u0430 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438 \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 \\u0438\\u0445 \\u0442\\u0432\\u043e\\u0440\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u0438\\u043d\\u0438\\u0446\\u0438\\u0430\\u0442\\u0438\\u0432;\",\"\\u0423\\u043b\\u0443\\u0447\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0434\\u0443\\u0445\\u043e\\u0432\\u043d\\u043e-\\u043d\\u0440\\u0430\\u0432\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b \\u0432 \\u0433\\u0440\\u0443\\u043f\\u043f\\u0430\\u0445;\",\"\\u0424\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0438\\u0434\\u0435\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0438\\u043c\\u043c\\u0443\\u043d\\u0438\\u0442\\u0435\\u0442\\u0430 \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u0440\\u0435\\u043b\\u0438\\u0433\\u0438\\u043e\\u0437\\u043d\\u043e\\u0433\\u043e \\u044d\\u043a\\u0441\\u0442\\u0440\\u0435\\u043c\\u0438\\u0437\\u043c\\u0430 \\u0438 \\u0442\\u0435\\u0440\\u0440\\u043e\\u0440\\u0438\\u0437\\u043c\\u0430;\",\"\\u