(40, 10, 'ar', 'قسم تنظيم الأنشطة البحثية للطلاب الموهوبين', 'بحرينيسو باختياروفنا توراقولوفا', 'رئيسة قسم تنظيم الأنشطة البحثية للطلاب الموهوبين', NULL, 'الثلاثاء – الخميس (09:00 - 05:00)', 'يهدف القسم إلى رعاية واكتشاف الطاقات الفكرية والإبداعية والابتكارية لدى الطلاب وتوجيههم نحو النشاط البحثي والمشاريع الناشئة.', '[\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u062a\\u062d\\u062f\\u064a\\u062b \\u0642\\u0627\\u0639\\u062f\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0645\\u0648\\u062d\\u062f\\u0629 \\u0644\\u0644\\u0634\\u0628\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0647\\u0648\\u0628\\u064a\\u0646 \\u0628\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0629\\u061b\",\"\\u062a\\u0646\\u0638\\u064a\\u0645 \\u062a\\u062f\\u0631\\u064a\\u0628 \\u0645\\u0643\\u062b\\u0641 \\u0648\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0648\\u0647\\u0648\\u0628\\u064a\\u0646 \\u0644\\u0644\\u0645\\u0633\\u0627\\u0628\\u0642\\u0627\\u062a \\u0648\\u0627\\u0644\\u0623\\u0648\\u0644\\u0645\\u0628\\u064a\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0639\\u0644\\u0645\\u064a\\u0629\\u061b\",\"\\u062f\\u0639\\u0645 \\u0648\\u062a\\u0637\\u0648\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0643\\u0627\\u0631\\u064a\\u0629 \\u0648\\u062d\\u0627\\u0636\\u0646\\u0627\\u062a \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644 \\u0648\\u062d\\u062b\\u0647\\u0645 \\u0639\\u0644\\u0649 \\u0631\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0623\\u0639\\u0645\\u0627\\u0644\\u061b\",\"\\u062a\\u0633\\u0647\\u064a\\u0644 \\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0647\\u0648\\u0628\\u064a\\u0646 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0643\\u0632 \\u0648\\u0627\\u0644\\u062c\\u0627\\u0645\\u0639\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0631\\u0627\\u0626\\u062f\\u0629\\u061b\",\"\\u062a\\u0623\\u0633\\u064a\\u0633 \\u0645\\u062c\\