INSERT INTO `web_footer_translations` (`id`, `web_footer_id`, `locale`, `logo_alt`, `description`, `useful_links_title`, `faculties_title`, `contact_title`, `address_line_1`, `address_line_2`, `phone_label`, `email_label`, `rights_text`, `useful_link_labels`, `faculty_link_labels`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'BSTU', 'Bukhara State Technical University (BSTU) is a premier higher education and scientific research hub in Central Asia, preparing elite specialists in engineering and digital technologies.', 'Useful Links', 'Faculties', 'Contact Us', 'Bukhara city, Murtazaev street, 15', 'Bukhara region, Republic of Uzbekistan', 'Phone:', 'Email:', 'All Rights Reserved BSTU © 2026', '{"home":"Home","about":"About","programs":"Programs","services":"Services","contact":"Contact"}', '{"engineering":"Faculty of Engineering","technology":"Faculty of Technology","service":"Faculty of Service and Digitalization","natural":"Faculty of Natural Resources Management"}', '2026-07-16 02:36:10', '2026-07-30 18:36:56'),
(2, 1, 'uz', 'BDTU', 'Buxoro davlat texnika universiteti (BSTU) Markaziy Osiyodagi yetakchi oliy taʼlim va ilmiy tadqiqot markazi bo‘lib, muhandislik va raqamli texnologiyalar bo‘yicha yuqori malakali mutaxassislar tayyorlaydi.', 'Foydali havolalar', 'Fakultetlar', 'Biz bilan bog‘laning', 'Buxoro shahri, Murtazayev ko‘chasi, 15', 'Buxoro viloyati, O‘zbekiston Respublikasi', 'Telefon:', 'Email:', 'Barcha huquqlar himoyalangan BSTU © 2026', '{"home":"Bosh sahifa","about":"Biz haqimizda","programs":"Dasturlar","services":"Xizmatlar","contact":"Aloqa"}', '{"engineering":"Muhandislik fakulteti","technology":"Texnologiya fakulteti","service":"Xizmat ko‘rsatish va raqamlashtirish fakulteti","natural":"Tabiiy resurslarni boshqarish fakulteti"}', '2026-07-16 02:36:10', '2026-07-30 18:36:56'),
(3, 1, 'ru', 'Бгту', 'Бухарский государственный технический университет (BSTU) является ведущим центром высшего образования и научных исследований в Центральной Азии, готовящим высококвалифицированных специалистов в инженерии и цифровых технологиях.', 'Полезные ссылки', 'Факультеты', 'Свяжитесь с нами', 'город Бухара, улица Муртазаева, 15', 'Бухарская область, Республика Узбекистан', 'Телефон:', 'Email:', 'Все права защищены BSTU © 2026', '{"home":"Главная","about":"О нас","programs":"Программы","services":"Услуги","contact":"контакт"}', '{"engineering":"Инженерный факультет","technology":"Факультет технологий","service":"Факультет сервиса и цифровизации","natural":"Факультет управления природными ресурсами"}', '2026-07-16 02:36:11', '2026-07-30 18:36:56'),
(4, 1, 'ar', 'جامعة بخارا التقنية الحكومية', 'جامعة بخارى التقنية الحكومية (BSTU) هي مركز رائد للتعليم العالي والبحث العلمي في آسيا الوسطى، وتعد نخبة من المتخصصين في الهندسة والتقنيات الرقمية.', 'روابط مفيدة', 'الكليات', 'اتصل بنا', 'مدينة بخارى، شارع مورتازاييف، 15', 'منطقة بخارى، جمهورية أوزبكستان', 'الهاتف:', 'البريد الإلكتروني:', 'جميع الحقوق محفوظة BSTU © 2026', '{"home":"الرئيسية","about":"من نحن","programs":"البرامج","services":"الخدمات","contact":"تواصل معنا"}', '{"engineering":"كلية الهندسة","technology":"كلية التكنولوجيا","service":"كلية الخدمات والرقمنة","natural":"كلية إدارة الموارد الطبيعية"}', '2026-07-16 02:36:11', '2026-07-30 18:36:56');
